function customerBookingFilter(filter,button){
 $$('.tabs button').forEach(x=>x.classList.remove('active')); button?.classList.add('active');
 const customer=currentCustomer(); const bs=getBookingsForCustomer(customer?.id||"c1");
 const today=new Date().toISOString().slice(0,10);
 const rows=filter==='upcoming'?bs.filter(b=>b.date>=today&&isActive(b)):filter==='active'?bs.filter(isActive):filter==='completed'?bs.filter(b=>b.status===BOOKING_STATUSES.COMPLETED):filter==='cancelled'?bs.filter(b=>b.status===BOOKING_STATUSES.CANCELLED):bs;
 const el=$('#customerBookingList'); if(el)el.innerHTML=rows.map(b=>bookingPanel(b,false)).join("")||emptyState("No bookings in this view","Try another filter or create a new service request.");
}

function workerEarnings(w){const completed=getBookingsForWorker(w?.id).filter(b=>b.status===BOOKING_STATUSES.COMPLETED);const paid=getState().payments.filter(p=>p.type==="service"&&p.status===PAYMENT_STATUSES.PAID&&completed.some(b=>b.id===p.bookingId)).reduce((n,p)=>n+Number(p.amount||0),0);const pending=getState().payments.filter(p=>p.status===PAYMENT_STATUSES.PENDING&&getBookingsForWorker(w?.id).some(b=>b.id===p.bookingId)).reduce((n,p)=>n+Number(p.amount||0),0);return {completed:`₹${paid.toLocaleString()}`,pending:`₹${pending.toLocaleString()}`,jobs:completed.length}}
function workerJob(b){const steps=[BOOKING_STATUSES.ACCEPTED,BOOKING_STATUSES.ON_THE_WAY,BOOKING_STATUSES.ARRIVED,BOOKING_STATUSES.INSPECTION,BOOKING_STATUSES.ESTIMATE_PENDING,BOOKING_STATUSES.CUSTOMER_DECISION,BOOKING_STATUSES.SERVICE_IN_PROGRESS,BOOKING_STATUSES.COMPLETED];const idx=steps.indexOf(b.status);const a=getAssignmentsForBooking(b.id).find(x=>x.workerId===worker?.id);let action="";if(a?.status===ASSIGNMENT_STATUSES.PENDING||a?.status===ASSIGNMENT_STATUSES.ASSIGNED)action=`<button class="btn btn-primary" onclick="workerDecision('${b.id}','accept')">Accept</button><button class="btn btn-light" onclick="workerDecision('${b.id}','reject')">Reject</button>`;else if(b.status===BOOKING_STATUSES.ACCEPTED&&a?.status===ASSIGNMENT_STATUSES.ACCEPTED)action=`<button class="btn btn-primary" onclick="advanceWorker('${b.id}','${BOOKING_STATUSES.ON_THE_WAY}')">Mark On the Way →</button>`;else if(b.status===BOOKING_STATUSES.ON_THE_WAY&&a?.status===ASSIGNMENT_STATUSES.ACCEPTED)action=`<button class="btn btn-primary" onclick="advanceWorker('${b.id}','${BOOKING_STATUSES.ARRIVED}')">Mark Arrived →</button>`;else if(b.status===BOOKING_STATUSES.ARRIVED&&a?.status===ASSIGNMENT_STATUSES.ACCEPTED)action=`<button class="btn btn-primary" onclick="advanceWorker('${b.id}','${BOOKING_STATUSES.INSPECTION}')">Start Inspection →</button>`;else if(b.status===BOOKING_STATUSES.INSPECTION&&a?.status===ASSIGNMENT_STATUSES.ACCEPTED)action=`<button class="btn btn-primary" onclick="openEstimate('${b.id}')">Submit Estimate</button>`;else if(b.status===BOOKING_STATUSES.CUSTOMER_DECISION)action=`<span class="status-pill amber">Waiting for customer decision</span>`;else if(b.status===BOOKING_STATUSES.SERVICE_IN_PROGRESS&&a?.status===ASSIGNMENT_STATUSES.ACCEPTED)action=`<button class="btn btn-primary" onclick="advanceWorker('${b.id}','${BOOKING_STATUSES.COMPLETED}')">Complete Service</button>`;return `<article class="lifecycle-card"><div class="panel-head"><div><span class="status-pill ${statusClass(b.status)}">${bookingStatusLabel(b.status)}</span><h3>${SERVICES.find(s=>s.id===b.service)?.name||b.service}</h3><small>${b.id} · ${formatDate(b.date)} · ${b.time}</small></div><span class="avatar">${worker?.avatar||"WK"}</span></div><div class="timeline">${steps.map((s,i)=>`<span class="${i<=idx?"done":""}"><i>${i<idx?"✓":i+1}</i>${bookingStatusLabel(s)}</span>`).join("")}</div><div class="panel-grid"><span>Customer <b>${getCustomerById(b.customerId)?.name||b.customer||"—"}</b></span><span>Location <b>${b.location||"—"}</b></span><span>Inspection <b>₹${b.inspectionCharge||0}</b></span></div><div class="panel-actions">${action}<button class="btn btn-light" onclick="openChat('${b.id}')">Message</button><button class="btn btn-light" onclick="demoCall()">Call</button></div></article>`}
function escHtml(value){return String(value??"").replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[ch]));}
function insuranceCopy(){const lang=getState().language||"en";return {en:{eyebrow:"WORKER WELFARE",title:"Insurance & Welfare",sub:"Demo insurance, cooperative welfare, claims and worker development information — all linked to your worker profile."},mr:{eyebrow:"कामगार कल्याण",title:"विमा आणि कल्याण",sub:"तुमच्या कामगार प्रोफाइलशी जोडलेली डेमो विमा, सहकारी कल्याण, दावे आणि प्रशिक्षण माहिती."},hi:{eyebrow:"कामगार कल्याण",title:"बीमा और कल्याण",sub:"आपकी कामगार प्रोफ़ाइल से जुड़ी डेमो बीमा, सहकारी कल्याण, दावे और प्रशिक्षण जानकारी."}}[lang]||{eyebrow:"WORKER WELFARE",title:"Insurance & Welfare",sub:"Demo worker welfare information."};}
