 const state=getState(),ins=getWorkerInsurance(w.id)||phase5InsuranceFor(w.id),wel=getWorkerWelfare(w.id)||phase5WelfareFor(w.id),claims=getWorkerClaims(w.id),c=insuranceCopy();
 const coverage=[['accident','Accidental Injury'],['workAccident','Work-related Accident'],['hospitalization','Hospitalization / Medical Assistance'],['temporaryDisability','Temporary Disability Support'],['permanentDisability','Permanent Disability Support'],['other','Other Cooperative Welfare Benefits']];
 const claimRows=claims.length?claims.map(cl=>`<tr><td>${escHtml(cl.id)}</td><td>${escHtml(cl.claimType)}</td><td>${formatDate(cl.incidentDate)}</td><td>₹${Number(cl.amount||0).toLocaleString()}</td><td><span class="status-pill ${cl.status==='APPROVED'||cl.status==='SETTLED'?'green':cl.status==='REJECTED'?'red':'amber'}">${escHtml(cl.status)}</span></td><td>${formatDate((cl.updatedAt||cl.createdAt||'').slice(0,10))}</td></tr>`).join(''):`<tr><td colspan="6">No demo claims recorded.</td></tr>`;
