 return `<div class="insurance-page"><div class="welcome"><div><span class="eyebrow">${c.eyebrow}</span><h2>${c.title}</h2><p>${c.sub}</p></div><span class="status-pill ${insuranceStatusClass(status)}">${insuranceStatusLabel(status)}</span></div><div class="prototype-banner">DEMO / PROTOTYPE INFORMATION — No real insurance policy, claim, enrollment or payment has been issued or submitted.</div><div class="insurance-grid"><article class="info-card insurance-hero-card"><div class="card-kicker">Insurance Overview</div><div class="insurance-status-row"><div><small>Status</small><h3>${insuranceStatusLabel(status)}</h3></div><span class="status-pill ${insuranceStatusClass(status)}">${status}</span></div><div class="detail-grid"><span><b>Provider</b>${escHtml(ins.provider||'Not enrolled')}</span><span><b>Policy / Reference</b>${escHtml(ins.policyReference||'—')}</span><span><b>Coverage Type</b>${escHtml(ins.coverageType||'—')}</span><span><b>Coverage Amount</b>${ins.coverageAmount?'₹'+Number(ins.coverageAmount).toLocaleString():'—'}</span><span><b>Policy Start</b>${formatDate(ins.startDate)}</span><span><b>Expiry / Renewal</b>${formatDate(ins.expiryDate)} · ${escHtml(ins.renewalStatus||'—')}</span><span><b>Last Updated</b>${formatDate(ins.lastUpdated)}</span></div><div class="info-box">${statusMessage}</div>${status==='NOT_ENROLLED'?`<button class="btn btn-outline" onclick="toast('Demo enrollment information only — no real enrollment is processed.','info')">View Enrollment Information</button>`:''}${status==='EXPIRED'?`<button class="btn btn-outline" onclick="toast('Demo renewal information only — no real renewal is processed.','info')">View Renewal Information</button>`:''}</article><article class="info-card"><div class="card-kicker">Coverage</div><div class="coverage-list">${coverage.map(([key,label])=>`<div class="coverage-item"><span class="coverage-icon">${ins.coverage?.[key]?'✓':'—'}</span><div><b>${label}</b><small>${ins.coverage?.[key]?'Included in demo profile':'Not included in demo profile'}</small></div></div>`).join('')}</div></article></div><article class="info-card"><div class="card-kicker">Policy Details</div><div class="detail-grid"><span><b>Policy Reference</b>${escHtml(ins.policyReference||'—')}</span><span><b>Worker / Member ID</b>${escHtml(w.id)}</span><span><b>Provider</b>${escHtml(ins.provider||'—')}</span><span><b>Coverage Type</b>${escHtml(ins.coverageType||'—')}</span><span><b>Start Date</b>${formatDate(ins.startDate)}</span><span><b>Expiry Date</b>${formatDate(ins.expiryDate)}</span><span><b>Renewal Status</b>${escHtml(ins.renewalStatus||'—')}</span><span><b>Last Updated</b>${formatDate(ins.lastUpdated)}</span></div></article><article class="info-card"><div class="section-heading compact-head"><div><div class="card-kicker">Claims & Support</div><h3>Demo Claims</h3></div><button class="btn btn-primary" onclick="openDemoClaimForm('${w.id}')">Report Insurance Claim</button></div><div class="table-wrap"><table><thead><tr><th>Claim ID</th><th>Type</th><th>Incident</th><th>Amount</th><th>Status</th><th>Updated</th></tr></thead><tbody>${claimRows}</tbody></table></div><p class="prototype-note">Demo claim only — no real insurance claim has been submitted.</p></article><div class="insurance-grid"><article class="info-card"><div class="card-kicker">Worker Welfare Benefits</div><div class="welfare-list">${(wel.benefits||[]).map(b=>`<div class="welfare-item"><div><b>${escHtml(b.name)}</b><small>Cooperative demo benefit</small></div><span class="status-pill ${welfareStatusClass(b.status)}">${escHtml(b.status)}</span></div>`).join('')||'<p>No demo welfare benefits listed.</p>'}</div></article><article class="info-card"><div class="card-kicker">Cooperative Membership</div><div class="detail-grid"><span><b>Cooperative</b>${escHtml(getCooperativeById(w.cooperativeId)?.name||w.coop||'—')}</span><span><b>Membership</b>${escHtml(wel.membershipStatus||'—')}</span><span><b>Member ID</b>${escHtml(wel.membershipId||'—')}</span><span><b>Joining Date</b>${formatDate(wel.joiningDate)}</span></div><p class="prototype-note">Membership details are demo values from the centralized worker profile.</p></article></div><article class="info-card"><div class="card-kicker">Training & Safety</div><div class="training-grid"><div><h3>Skill Development</h3><p><b>Completed</b></p><ul>${(wel.training?.completed||[]).map(x=>`<li>${escHtml(x)}</li>`).join('')||'<li>None recorded</li>'}</ul><p><b>Available</b></p><ul>${(wel.training?.available||[]).map(x=>`<li>${escHtml(x)}</li>`).join('')||'<li>None listed</li>'}</ul><p><b>Upcoming</b></p><ul>${(wel.training?.upcoming||[]).map(x=>`<li>${escHtml(x)}</li>`).join('')||'<li>None scheduled</li>'}</ul></div><div><h3>Safety</h3><div class="safety-list"><span>✓ Safety orientation guidance</span><span>✓ Workplace safety guidance</span><span>✓ Protective equipment guidance</span></div><p class="prototype-note">Informational demo content. No legal certification is implied.</p></div></div></article></div>`;
