function openDemoClaimForm(workerId){
 if(role!=="worker"||worker?.id!==workerId)return;
 const today=new Date().toISOString().slice(0,10);
 $("#globalModal").classList.remove("hidden");$("#globalModalContent").innerHTML=`<button class="modal-close" onclick="closeGlobal()">×</button><span class="eyebrow">DEMO CLAIM</span><h2>Report Insurance Claim</h2><p>Enter prototype-safe information only. This does not submit a real insurance claim.</p><form id="demoClaimForm" class="form-grid"><label>Claim type *<select name="claimType" required><option value="">Select claim type</option><option>Accidental injury</option><option>Work-related accident</option><option>Hospitalization assistance</option><option>Other welfare support</option></select></label><label>Incident date *<input name="incidentDate" type="date" max="${today}" required></label><label class="full-field">Short description *<textarea name="description" maxlength="300" required placeholder="Brief demo description"></textarea></label><label>Optional demo amount<input name="amount" type="number" min="0" max="1000000" step="100" placeholder="e.g. 5000"></label><div class="full-field prototype-banner">Demo claim only — no real insurance claim has been submitted.</div><button class="btn btn-primary full-field" type="submit">Submit Demo Claim</button></form>`;
 $("#demoClaimForm").onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target);try{const claim=submitDemoInsuranceClaim(workerId,{claimType:fd.get('claimType'),incidentDate:fd.get('incidentDate'),description:fd.get('description'),amount:fd.get('amount')});closeGlobal();toast(`Demo claim ${claim.id} created. No real claim was submitted.`,'success');renderView('insurance');}catch(err){toast(err.message||'Unable to create demo claim.','error');}};
}
function federationAdminRequestPanel(b){
 const fedId=getFederationScope(),state=getState();
 const localWorkers=getWorkersForFederation(fedId).filter(w=>w.service===b.service&&(!b.cooperativeId||w.cooperativeId===b.cooperativeId));
 const matches=rankWorkers(localWorkers.map(w=>calculateMatchScore(w,b,state)).map(r=>({...r,worker:getWorkerById(r.workerId)})));
 const eligible=matches.filter(r=>r.eligible),ineligible=matches.filter(r=>!r.eligible),assignments=getAssignmentsForBooking(b.id),assistance=getAssistanceForBooking(b.id),cross=assistance?getAssistanceCandidates(assistance.id):[];
 const canRequest=(b.status===BOOKING_STATUSES.REQUESTED||b.status===BOOKING_STATUSES.ASSIGNMENT_PENDING)&&!eligible.length&&!assistance;
 const history=assignments.map(a=>`${getWorkerById(a.workerId)?.name||a.workerId} · ${a.status}${a.assignmentSource?` · ${a.assignmentSource.replace('_',' ')}`:''}`).join(' · ');
 return `<article class="booking-panel federation-admin-match-panel"><div class="panel-head"><div><span class="status-pill ${statusClass(b.status)}">${bookingStatusLabel(b.status)}</span><h3>${SERVICES.find(s=>s.id===b.service)?.name||b.service}</h3><small>${b.id} · ${formatDate(b.date)} · ${b.time}</small></div><span class="status-pill amber">${b.urgency||"Normal"}</span></div><div class="panel-grid"><span>Customer <b>${getCustomerById(b.customerId)?.name||b.customer||"—"}</b></span><span>Requirement <b>${b.requirement||"—"}</b></span><span>Location <b>${b.location||"—"}</b></span><span>Local Eligible <b>${eligible.length}</b></span></div>${eligible.length?`<div class="match-ranking"><h4>Local eligible workers</h4>${eligible.slice(0,5).map((r,i)=>`<div class="match-row"><div><strong>#${i+1} ${r.worker.name}</strong><small>${r.worker.skill} · ${r.eta.label} · ★ ${Number(r.worker.rating||0).toFixed(1)} · ${Number(r.worker.experience??r.worker.exp??0)} yrs</small></div><b>${r.score}%</b><button class="text-link" onclick="showMatchExplanation('${b.id}','${r.workerId}')">Why?</button></div>`).join('')}</div>`:`<div class="empty-state"><h3>No eligible local worker</h3><p>${escHtml(assistance?.reason||determineAssistanceReason(b))}</p>${canRequest?`<button class="btn btn-primary" onclick="requestFederationAssistance('${b.id}')">Request Federation Support</button>`:''}</div>`}${ineligible.length?`<details class="excluded-match"><summary>Local workers excluded (${ineligible.length})</summary><div class="excluded-list">${ineligible.slice(0,8).map(r=>`<div><b>${r.worker.name}</b><span>${escHtml(r.explanation.find(x=>x.includes('mismatch')||x.includes('Unavailable')||x.includes('Outside')||x.includes('pending'))||'Not eligible for this request.')}</span></div>`).join('')}</div></details>`:''}${assistance?`<section class="cross-support-panel"><div class="panel-head"><div><span class="eyebrow">CROSS-COOPERATIVE SUPPORT</span><h4>Federation Assistance · ${assistance.status}</h4><small>${escHtml(assistance.reason)}</small></div><span class="status-pill amber">${cross.length} candidate${cross.length===1?'':'s'}</span></div>${cross.length?cross.slice(0,5).map((r,i)=>`<div class="match-row"><div><strong>#${i+1} ${r.worker.name}</strong><small>${getCooperativeById(r.worker.cooperativeId)?.name||'Other cooperative'} · ${r.worker.skill} · ${r.eta.label} · ★ ${Number(r.worker.rating||0).toFixed(1)}</small></div><b>${r.score}%</b><button class="btn btn-primary btn-sm" onclick="selectFederationSupport('${assistance.id}','${r.workerId}')">Select</button><button class="text-link" onclick="showMatchExplanation('${b.id}','${r.workerId}')">Why?</button></div>`).join(''):emptyState('No cross-cooperative candidate','No eligible verified worker was found in another cooperative in this federation.')}</section>`:''}<div class="panel-actions">${(b.status===BOOKING_STATUSES.REQUESTED||b.status===BOOKING_STATUSES.ASSIGNMENT_PENDING)&&eligible.length?`<select id="assign-${b.id}"><option value="">Select ranked worker</option>${eligible.map(r=>`<option value="${r.workerId}">${r.worker.name} · ${r.score}% · ETA ${r.eta.label}</option>`).join('')}</select><button class="btn btn-primary" onclick="assignWorker('${b.id}')">Assign Worker</button>`:`<span class="status-pill blue">Worker: ${getBookingWorker(b)?.name||'Awaiting assignment'}</span>`}</div>${history?`<div class="estimate-mini"><b>Assignment history:</b> ${history}</div>`:''}</article>`;
}
function requestFederationAssistance(bookingId){if(role!=="federationAdmin")return;const b=getBookings().find(x=>x.id===bookingId);if(!b)return;const r=createAssistanceRequest(bookingId,determineAssistanceReason(b));if(r){toast("Federation assistance request created.","success");renderView("crossRequests");}}
function selectFederationSupport(requestId,workerId){if(role!=="federationAdmin")return;const result=selectCrossCooperativeWorker(requestId,workerId);if(!result)return toast("Worker is no longer eligible for cross-cooperative support.","error");toast(`Cross-cooperative worker ${result.assignment.workerId} selected.` ,"success");renderView("crossRequests");}
function stateForMatching(){return getState();}

function showMatchExplanation(bookingId,workerId){const b=getBookings().find(x=>x.id===bookingId),w=getWorkerById(workerId);if(!b||!w)return;const m=getWorkerMatchResult(workerId,b);if(!m)return;$("#globalModal").classList.remove("hidden");$("#globalModalContent").innerHTML=`<button class="modal-close" onclick="closeGlobal()">×</button><span class="eyebrow">RULE-BASED MATCHING</span><h2>${w.name} · ${m.score}% Match</h2><p>Deterministic recommendation using the current shared state. Verification is a mandatory eligibility gate.</p><div class="match-breakdown">${m.explanation.map(x=>`<div>✓ ${x}</div>`).join("")}</div><div class="detail-grid"><span><b>Distance</b>${m.distanceKm===null?"Demo":m.distanceKm+" km"}</span><span><b>Estimated ETA</b>${m.eta.label}</span><span><b>Workload</b>${m.workload} active job(s)</span><span><b>Cooperative capacity</b>${m.capacity.capacityStatus}</span></div>`}

function assignWorker(id){
 if(role!=="federationAdmin")return;
 const select=$("#assign-"+id),workerId=select?.value;if(!workerId)return toast("Select an eligible worker first.","error");
 const state=getState(),b=state.bookings.find(x=>x.id===id),w=state.workers.find(x=>x.id===workerId),c=currentFederationAdmin();if(!b||!w||!c)return;if(!canAccessBooking(c,b)||!canAccessWorkerProfile(c,w))return toast("You are not authorized to assign this worker.","error");
 const match=calculateMatchScore(w,b,state);if(!match.eligible)return toast(match.explanation.find(x=>x.includes("Not eligible")||x.includes("mismatch")||x.includes("Unavailable")||x.includes("Outside"))||"Worker is not eligible for this request.","error");
 const now=new Date().toISOString();b.primaryWorkerId=workerId;b.selectedWorkerIds=[...new Set([workerId,...(b.selectedWorkerIds||[])])];b.cooperativeId=w.cooperativeId;b.federationId=getCooperativeById(w.cooperativeId)?.federationId||b.federationId;b.status=BOOKING_STATUSES.ASSIGNED;b.matchScore=match.score;b.matchExplanation=match.explanation;b.updatedAt=now;
 state.assignments.push({id:`assign-${id}-${workerId}-${Date.now()}`,bookingId:id,workerId,assignedBy:c.id,cooperativeId:w.cooperativeId,status:ASSIGNMENT_STATUSES.ASSIGNED,assignedAt:now,acceptedAt:null,completedAt:null,historyType:"ASSIGNMENT",assignmentSource:"LOCAL_COOPERATIVE"});auditFederationAction("ASSIGN_WORKER",id,`Worker ${workerId} assigned through local cooperative matching.`);state.notifications.push({id:`notif-${Date.now()}`,userId:w.userId||w.id,type:"assignment",bookingId:id,message:`New service assignment ${id} is waiting for your response.`,createdAt:now,read:false});saveState(state);toast(`Worker ${w.name} assigned to ${id}.`);renderView("requests")
}
function openEstimate(id){const b=getBookings().find(x=>x.id===id);if(!b)return;$("#globalModal").classList.remove("hidden");$("#globalModalContent").innerHTML=`<button class="modal-close" onclick="closeGlobal()">×</button><h2>Submit Estimate</h2><p>${b.id} · Material and labour are stored in shared booking state.</p><div class="form-grid"><label>Material cost<input id="estimateMaterial" type="number" min="0" value="800"></label><label>Labour cost<input id="estimateLabour" type="number" min="0" value="1200"></label></div><label>Notes<textarea id="estimateNotes">Inspection completed. Proposed repair and testing.</textarea></label><div class="step-actions"><button class="btn btn-outline" onclick="closeGlobal()">Cancel</button><button class="btn btn-primary" onclick="submitEstimate('${id}')">Submit ₹<span id="estimateTotalPreview">2000</span></button></div>`;const update=()=>{$("#estimateTotalPreview").textContent=(Number($("#estimateMaterial").value||0)+Number($("#estimateLabour").value||0)).toLocaleString()};["#estimateMaterial","#estimateLabour"].forEach(id=>$(id).oninput=update)}
function cancelBooking(id){if(role!=="customer")return;$("#globalModal").classList.remove("hidden");$("#globalModalContent").innerHTML=`<button class="modal-close" onclick="closeGlobal()">×</button><h2>Cancel booking?</h2><p>This demo will update the shared booking and assignment records. No cancellation fee is invented.</p><div class="step-actions"><button class="btn btn-outline" onclick="closeGlobal()">Keep Booking</button><button class="btn btn-danger" onclick="confirmCancel('${id}')">Confirm Cancellation</button></div>`}
function openBooking(id){const b=getBookings().find(x=>x.id===id);if(!b)return;const w=getBookingWorker(b),estimate=b.estimate||getState().estimates.find(x=>x.bookingId===id),customer=getCustomerById(b.customerId);$("#globalModal").classList.remove("hidden");$("#globalModalContent").innerHTML=`<button class="modal-close" onclick="closeGlobal()">×</button><span class="status-pill ${statusClass(b.status)}">${bookingStatusLabel(b.status)}</span><h2>${SERVICES.find(s=>s.id===b.service)?.name||b.service}</h2><div class="detail-grid"><span><b>Booking ID</b>${b.id}</span><span><b>Customer</b>${customer?.name||"—"}</span><span><b>Worker</b>${w?.name||"Awaiting assignment"}</span><span><b>Date</b>${formatDate(b.date)}</span><span><b>Time</b>${b.time}</span><span><b>Location</b>${b.location||"—"}</span><span><b>Requirement</b>${b.requirement||"—"}</span><span><b>Urgency</b>${b.urgency||"Normal"}</span><span><b>Inspection</b>₹${b.inspectionCharge||0} · ${b.paymentStatus}</span><span><b>Estimate</b>${estimate?`₹${estimate.total}`:"Not submitted"}</span><span><b>Match</b>${b.matchScore?`${b.matchScore}% demo recommendation`:"Federation Administration assignment"}</span></div>${role==="customer"&&b.status===BOOKING_STATUSES.CUSTOMER_DECISION?`<div class="detail-actions"><button class="btn btn-primary" onclick="closeGlobal();customerEstimateDecision('${id}','accept')">Accept Estimate</button><button class="btn btn-danger" onclick="closeGlobal();customerEstimateDecision('${id}','decline')">Decline Estimate</button></div>`:""}<div class="detail-actions">${w&&["customer","worker"].includes(role)?`<button class="btn btn-outline" onclick="openChat('${id}')">Message</button><button class="btn btn-outline" onclick="demoCall()">☎ Demo Call</button>`:""}${role==="customer"&&isActive(b)?`<button class="btn btn-danger" onclick="closeGlobal();cancelBooking('${id}')">Cancel Booking</button>`:""}</div>`}
function closeGlobal(){$("#globalModal").classList.add("hidden")}
function chatMessagesHtml(id){const messages=getMessagesForBooking(id);if(!messages.length)return `<div class="chat-msg received">No messages yet. Start the demo conversation.</div>`;return messages.map(m=>`<div class="chat-msg ${m.senderId===currentUser()?.id?"sent":"received"}">${m.message}<small>${new Date(m.timestamp).toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"})}</small></div>`).join("")}
