/* ================= PHASE 4 UI: VERIFICATION ================= */
navs.worker.splice(1,0,["verification","Skill Verification"]);

function verificationStatusClass(s){return s==="VERIFIED"?"green":s==="FAILED"||s==="SUSPENDED"?"red":s==="TEST_SCHEDULED"?"blue":"amber"}
function verificationStatusLabel(s){return ({PENDING:"Pending",TEST_SCHEDULED:"Test Scheduled",TEST_ATTENDED:"Test Attended",VERIFIED:"Verified",FAILED:"Failed",SUSPENDED:"Suspended"})[s]||s||"—"}
function verificationAppointmentFor(workerId){return workerVerification(workerId)?.appointment||null}
function verificationCenterName(id){return getState().verificationCenters.find(c=>c.id===id)?.name||"—"}
function verificationSkillName(id){return SERVICES.find(s=>s.id===id)?.name||id||"—"}
function workerVerificationCard(w,federationAdminView=false){
 const vr=workerVerification(w.id)||{status:w.verificationStatus}; const a=vr.appointment; const details=vr.details||{};
 const eligible=isVerifiedWorker(w.id);
 return `<article class="verification-card booking-panel"><div class="panel-head"><div><span class="status-pill ${verificationStatusClass(w.verificationStatus)}">${verificationStatusLabel(w.verificationStatus)}</span><h3>${w.name}</h3><small>${w.id} · ${w.skill} · ${w.experience||w.exp||0} years experience</small></div><span class="avatar">${w.avatar||"WK"}</span></div><div class="panel-grid"><span>Skills <b>${(w.skills||[w.skill]).join(", ")}</b></span><span>Cooperative <b>${getCooperativeById(w.cooperativeId)?.name||w.coop||"—"}</b></span><span>Test center <b>${a?verificationCenterName(a.centerId):"Not scheduled"}</b></span><span>Test date <b>${a?`${formatDate(a.date)} · ${a.timeSlot}`:"—"}</b></span></div>${w.verificationStatus==="PENDING"&&!a?`<div class="info-box"><b>Your account has been registered successfully, but your skills have not yet been verified.</b><br>You must pass an offline skill verification test before becoming eligible for verified service assignments.</div>`:""}${w.verificationStatus==="FAILED"?`<div class="error-box">Your skill verification was not successful. Please contact your cooperative for further assistance.</div>`:""}${w.verificationStatus==="VERIFIED"?`<div class="estimate-mini">✓ You are now eligible for verified-worker matching.${details.verifiedSkills?.length?` Verified skills: <b>${details.verifiedSkills.join(", ")}</b>`:""}</div>`:""}${a&&a.status==="SCHEDULED"?`<div class="estimate-mini">Offline test scheduled. This prototype records the appointment only; the physical test happens offline.</div>`:""}${federationAdminView&&a?`<div class="panel-actions">${a.status==="SCHEDULED"?`<button class="btn btn-primary" onclick="markTestAttended('${w.id}')">Mark Test Attended</button>`:""}${a.status==="ATTENDED"||w.verificationStatus==="TEST_ATTENDED"?`<button class="btn btn-primary" onclick="openVerificationResult('${w.id}','pass')">Record PASS</button><button class="btn btn-danger" onclick="openVerificationResult('${w.id}','fail')">Record FAIL</button>`:""}</div>`:""}${!federationAdminView&&w.verificationStatus!=="VERIFIED"&&w.verificationStatus!=="FAILED"?`<div class="panel-actions"><button class="btn btn-primary" onclick="openVerificationScheduler('${w.id}')">${a&&a.status==="SCHEDULED"?"View / Reschedule Test":"Schedule Offline Test"}</button>${a&&a.status==="SCHEDULED"?`<button class="btn btn-light" onclick="cancelVerificationAppointment('${w.id}')">Cancel</button>`:""}</div>`:""}</article>`
}

function verificationPage(w){
 if(!w)return emptyState("Worker profile unavailable","Sign in through the worker demo or complete registration first.");
 return `<div class="welcome"><div><span class="eyebrow">SKILL VERIFICATION</span><h2>Offline Skill Verification</h2><p>The actual skill test is conducted physically. Co-opGig only manages the appointment and verification status.</p></div><span class="status-pill ${verificationStatusClass(w.verificationStatus)}">${verificationStatusLabel(w.verificationStatus)}</span></div>${workerVerificationCard(w,false)}`;
}

function openVerificationScheduler(workerId){
 if(role!=="worker"||worker?.id!==workerId)return;
 const state=getState(),w=getWorkerById(workerId);if(!w)return;
 const existing=verificationAppointmentFor(workerId);
 const eligibleCenters=state.verificationCenters.filter(c=>c.supportedSkills.includes(w.service));
 if(!eligibleCenters.length)return toast("No demo verification center supports this skill.","error");
 const selectedCenter=existing?.centerId||eligibleCenters[0].id;
 const selectedDate=existing?.date||state.verificationDates.find(d=>getAvailableVerificationSlots(selectedCenter,d,workerId).length)||state.verificationDates[0];
 const selectedSlot=existing?.timeSlot||getAvailableVerificationSlots(selectedCenter,selectedDate,workerId)[0]||"";
 const render=()=>{
  const centerId=$("#verificationCenter")?.value||selectedCenter,date=$("#verificationDate")?.value||selectedDate;
  const dates=state.verificationDates.filter(d=>getAvailableVerificationSlots(centerId,d,workerId).length||d===existing?.date);
  const slots=getAvailableVerificationSlots(centerId,date,workerId);
  const currentSlot=$("#verificationSlot")?.value||selectedSlot;
  $("#verificationCenter").innerHTML=eligibleCenters.map(c=>`<option value="${c.id}" ${c.id===centerId?"selected":""}>${c.name} — ${c.address}</option>`).join("");
  $("#verificationDate").innerHTML=dates.map(d=>`<option value="${d}" ${d===date?"selected":""}>${formatDate(d)}</option>`).join("");
  $("#verificationSlot").innerHTML=slots.map(s=>`<option value="${s}" ${s===currentSlot?"selected":""}>${s}</option>`).join("")||`<option value="">No slots available</option>`;
  $("#verificationCenter").onchange=()=>{const c=$("#verificationCenter").value;const first=state.verificationDates.find(d=>getAvailableVerificationSlots(c,d,workerId).length);if(first)$("#verificationDate").value=first;render()};
  $("#verificationDate").onchange=render;
 };
 $("#globalModal").classList.remove("hidden");
 $("#globalModalContent").innerHTML=`<button class="modal-close" onclick="closeGlobal()">×</button><span class="eyebrow">OFFLINE APPOINTMENT</span><h2>Schedule Offline Skill Verification Test</h2><p>Select one demo center, future date and available time slot. The physical test is not conducted online.</p><div class="form-grid"><label>Verification Center<select id="verificationCenter"></select></label><label>Date<select id="verificationDate"></select></label><label>Available Time Slot<select id="verificationSlot"></select></label><label>Skill<input value="${w.skill}" disabled></label></div><div class="info-box">Demo information only. Appointment availability is stored in shared LocalStorage state.</div><div class="step-actions"><button class="btn btn-outline" onclick="closeGlobal()">Cancel</button><button class="btn btn-primary" onclick="confirmVerificationAppointment('${workerId}')">Confirm Test Appointment</button></div>`;
 render();
}
function confirmVerificationAppointment(workerId){
 if(role!=="worker"||worker?.id!==workerId)return;
 const centerId=$("#verificationCenter")?.value,date=$("#verificationDate")?.value,timeSlot=$("#verificationSlot")?.value;if(!centerId||!date||!timeSlot)return toast("Select a center, date and available time slot.","error");
 const available=getAvailableVerificationSlots(centerId,date,workerId);const existing=verificationAppointmentFor(workerId);if(!available.includes(timeSlot)&&existing?.timeSlot!==timeSlot)return toast("That time slot is no longer available.","error");
 const state=getState(),now=new Date().toISOString();const id=existing?.id||`vappt-${workerId}-${Date.now()}`;
 const appointment={id,verificationAppointmentId:id,workerId,centerId,skill:getWorkerById(workerId)?.service,date,timeSlot,status:"SCHEDULED",createdAt:existing?.createdAt||now,updatedAt:now};
 state.verificationAppointments[id]=appointment;
 const w=state.workers.find(x=>x.id===workerId);if(w){w.verificationStatus="TEST_SCHEDULED";w.verificationDetails={...(w.verificationDetails||{}),appointmentId:id,centerId,date,timeSlot};state.verification[workerId]={id:state.verification[workerId]?.id||`ver-${workerId}`,workerId,status:"TEST_SCHEDULED",verificationDetails:deepClone(w.verificationDetails)};}
 state.notifications.push({id:`notif-${Date.now()}`,userId:w?.userId||workerId,type:existing?"verification_rescheduled":"verification_scheduled",message:existing?`Offline skill verification test rescheduled to ${formatDate(date)} at ${timeSlot}.`:`Offline skill verification test scheduled for ${formatDate(date)} at ${timeSlot}.`,createdAt:now,read:false});
 saveState(state);closeGlobal();toast(existing?"Verification appointment rescheduled.":"Verification appointment scheduled.");renderView("verification");
}
function cancelVerificationAppointment(workerId){
 if(role!=="worker"||worker?.id!==workerId)return;const state=getState(),a=verificationAppointmentFor(workerId);if(!a)return;const now=new Date().toISOString();a.status="CANCELLED";a.cancelledAt=now;a.updatedAt=now;const w=state.workers.find(x=>x.id===workerId);if(w){w.verificationStatus="PENDING";w.verificationDetails={};state.verification[workerId]={id:state.verification[workerId]?.id||`ver-${workerId}`,workerId,status:"PENDING",verificationDetails:{}};}state.notifications.push({id:`notif-${Date.now()}`,userId:w?.userId||workerId,type:"verification_cancelled",message:"Offline skill verification appointment cancelled. Your verification status is Pending.",createdAt:now,read:false});saveState(state);toast("Verification appointment cancelled.","info");renderView("verification");
}
function markTestAttended(workerId){
 if(role!=="federationAdmin")return;const state=getState(),w=state.workers.find(x=>x.id===workerId),c=currentFederationAdmin(),a=verificationAppointmentFor(workerId);if(!w||!c||!a||a.status!=="SCHEDULED")return;const now=new Date().toISOString();a.status="ATTENDED";a.attendanceDate=now.slice(0,10);a.attendedBy=c.id;a.updatedAt=now;w.verificationStatus="TEST_ATTENDED";w.verificationDetails={...(w.verificationDetails||{}),testDate:a.attendanceDate,attendedBy:c.id,centerId:a.centerId,timeSlot:a.timeSlot};state.verification[workerId]={id:state.verification[workerId]?.id||`ver-${workerId}`,workerId,status:"TEST_ATTENDED",verificationDetails:deepClone(w.verificationDetails)};auditFederationAction("VERIFICATION_RESULT",workerId,`Offline skill test attendance recorded for ${w.name}.`);state.notifications.push({id:`notif-${Date.now()}`,userId:w.userId||workerId,type:"verification_attended",message:"Federation Administration recorded your offline skill test as attended. A result is now pending.",createdAt:now,read:false});saveState(state);toast(`${w.name}: test attendance recorded.`);renderView("verification");
}
function openVerificationResult(workerId,result){
 if(role!=="federationAdmin")return;const w=getWorkerById(workerId);if(!w||w.verificationStatus!=="TEST_ATTENDED")return;
 $("#globalModal").classList.remove("hidden");$("#globalModalContent").innerHTML=`<button class="modal-close" onclick="closeGlobal()">×</button><h2>Record Verification Result</h2><p><b>${w.name}</b> · ${w.skill}</p><div class="form-grid"><label>Result<input value="${result.toUpperCase()}" disabled></label><label>Verified skill/category<input id="verifiedSkillsInput" value="${(w.skills||[w.skill]).join(", ")}"></label></div><label>Federation Administration remarks<textarea id="verificationRemarks" placeholder="Enter demo remarks."></textarea></label><div class="info-box">This records the Federation Administration's explicit result for an offline physical test. The website does not conduct or fake the examination.</div><div class="step-actions"><button class="btn btn-outline" onclick="closeGlobal()">Cancel</button><button class="btn ${result==="pass"?"btn-primary":"btn-danger"}" onclick="recordVerificationResult('${workerId}','${result}')">Record ${result.toUpperCase()}</button></div>`;
}
function recordVerificationResult(workerId,result){
 if(role!=="federationAdmin"&&role!=="admin")return;const state=getState(),w=state.workers.find(x=>x.id===workerId),c=currentFederationAdmin();if(!w)return;if(role==="federationAdmin"&&!canManageVerification(currentUser(),w))return toast("You are not authorized to manage this worker verification.","error");if(w.verificationStatus!=="TEST_ATTENDED")return;const now=new Date().toISOString(),skills=($("#verifiedSkillsInput")?.value||w.skill).split(",").map(x=>x.trim()).filter(Boolean),remarks=$("#verificationRemarks")?.value.trim()||"";const status=result==="pass"?"VERIFIED":"FAILED";if(status==="VERIFIED"&&!w.employeeId){const nums=state.workers.map(x=>Number(String(x.employeeId||"").replace(/\D/g,"")||0)).filter(Number.isFinite);w.employeeId=`CG-W-${Math.max(1000,...nums)+1}`;}w.verificationStatus=status;w.verificationDetails={...(w.verificationDetails||{}),testDate:w.verificationDetails?.testDate||now.slice(0,10),verifiedBy:c.id,verifiedSkills:status==="VERIFIED"?skills:[],remarks};state.verification[workerId]={id:state.verification[workerId]?.id||`ver-${workerId}`,workerId,status,verificationDetails:deepClone(w.verificationDetails)};auditFederationAction("VERIFICATION_RESULT",workerId,`Offline skill verification result recorded: ${status}.`);const a=verificationAppointmentFor(workerId);if(a){a.result=status;a.resultRecordedAt=now;a.resultRecordedBy=c.id;a.remarks=remarks;a.updatedAt=now;}state.notifications.push({id:`notif-${Date.now()}`,userId:w.userId||workerId,type:status==="VERIFIED"?"verification_passed":"verification_failed",message:status==="VERIFIED"?"Your offline skill verification passed. You are eligible for verified-worker matching.":"Your offline skill verification was not successful. Please contact your cooperative for further assistance.",createdAt:now,read:false});saveState(state);closeGlobal();toast(status==="VERIFIED"?`${w.name} is now verified and eligible.`:`${w.name} marked as failed.`,status==="VERIFIED"?"success":"info");renderView("verification");
}

function renderWorker(v,e){
 const workerId=worker?.id,mine=workerId?getBookingsForWorker(workerId):[];
 if(v==="verification")e.innerHTML=verificationPage(worker);
 else if(v==="overview"){
  const b=mine.find(isActive)||mine[0],vr=worker?workerVerification(worker.id):null;
  e.innerHTML=`<div class="welcome"><div><span class="eyebrow">WORKER</span><h2>Good evening, ${worker?.name||user.name}.</h2><p>Move assigned jobs through the shared service lifecycle.</p></div><span class="status-pill ${worker?.online?"green":"amber"}">● ${worker?.online?"Available":"Offline"}</span></div><div class="info-box"><b>Employee ID:</b> ${escHtml(worker?.employeeId||"Pending verification")}</div><div class="kpi-grid">${kpi("Assigned jobs",mine.filter(x=>![BOOKING_STATUSES.COMPLETED,BOOKING_STATUSES.CANCELLED].includes(x.status)).length,"Central assignments")} ${kpi("Completed jobs",mine.filter(x=>x.status===BOOKING_STATUSES.COMPLETED).length,"This demo state")} ${kpi("Earnings",workerEarnings(worker).completed,"Derived from payments")} ${kpi("Verification",verificationStatusLabel(worker?.verificationStatus),"Skill verification")}</div>${worker?.verificationStatus!=="VERIFIED"?workerVerificationCard(worker,false):""}${b?workerJob(b):emptyState("No assigned jobs","The federationAdmin must assign a service request to this worker.")}`;
 } else if(v==="jobs"){e.innerHTML=mine.map(workerJob).join("")||emptyState("No jobs","Assigned jobs appear here after Federation Administration assignment.");}
 else if(v==="availability"){const a=getState().availability[workerId]||{};e.innerHTML=`<div class="availability-card"><div class="availability-head"><div><h2>Availability</h2><p>Central demo availability for ${worker?.name||"worker"}.</p></div><span class="status-pill ${worker?.online?"green":"amber"}">${worker?.online?"Available":"Offline"}</span></div><div class="week-grid">${["Mon","Tue","Wed","Thu","Fri","Sat","Sun"].map(d=>`<label class="day-box"><input type="checkbox" checked><b>${d}</b><small>09:00–19:00</small></label>`).join("")}</div><button class="btn btn-primary" onclick="saveWorkerAvailability()">Save Availability</button></div>`;}
 else if(v==="earnings"){const earn=workerEarnings(worker);e.innerHTML=`<div class="kpi-grid">${kpi("Completed payments",earn.completed,"Central payment data")} ${kpi("Pending",earn.pending,"Estimate/service payment pending")} ${kpi("Completed jobs",earn.jobs,"Central booking history")}</div>`;}
 else if(v==="reviews"){const reviews=getReviewsForWorker(workerId);e.innerHTML=`<div class="profile-head"><span class="avatar huge">${worker?.avatar||"WK"}</span><div><h2>${worker?.name||"Worker"}</h2><p>${worker?.skill||""}</p><strong class="profile-rating">★ ${worker?.rating||"—"}</strong> · ${reviews.length} reviews</div></div><div class="review-list">${reviews.map(r=>`<blockquote><b>Customer review</b><span>★★★★★</span><p>${escHtml(r.comment)}</p><small>${r.category||"Service"}</small></blockquote>`).join("")||emptyState("No reviews","Completed service reviews will appear here.")}</div>`;}
 else if(v==="profile"){e.innerHTML=profilePage(worker?{...user,...worker,initials:worker.avatar,role:"Worker"}:user);}
 else if(v==="messages"){const b=mine[0];const c=b?getCustomerById(b.customerId):null;e.innerHTML=b?`<div class="chat-page"><div class="chat-list"><h3>Conversations</h3><div class="chat-person active"><span class="avatar">${c?.initials||"CU"}</span><div><b>${c?.name||"Customer"}</b><small>${b.id}</small></div></div></div><div class="chat-area"><div class="chat-head"><span class="avatar">${c?.initials||"CU"}</span><div><b>${c?.name||"Customer"}</b><small>Customer</small></div></div><div class="chat-window">${chatMessagesHtml(b.id)}</div><div class="chat-compose"><input id="dashChat" placeholder="Type a message…"><button class="btn btn-primary" onclick="dashSend()">Send</button></div></div></div>`:emptyState("No conversations","Assigned jobs create customer conversations.");}
 else e.innerHTML=emptyState("Support","Demo worker support content.");
}

function federationWorkers(){return getWorkersForFederation(getFederationScope());}
function federationBookings(){return getBookingsForFederationScoped(getFederationScope());}
function federationCoops(){return getCooperativesForFederation(getFederationScope());}
function workloadFor(w){return workerWorkload(w.id,getState());}
function federationWorkerStatus(w){if(w.suspended)return "Suspended";if(w.active===false)return "Inactive";if(w.online===false)return "Offline";return workloadFor(w)>0?"Busy":"Available";}
function federationWorkerRow(w){const a=getState().assignments.find(x=>x.workerId===w.id&&!['REJECTED','CANCELLED','COMPLETED'].includes(x.status));const b=a?getState().bookings.find(x=>x.id===a.bookingId):null;return `<tr><td><span class="table-person"><span class="avatar">${w.avatar||"WK"}</span>${w.name}</span><small>${w.id}</small></td><td>${w.skill||"—"}</td><td>${getCooperativeById(w.cooperativeId)?.name||"—"}</td><td><span class="status-pill ${verificationStatusClass(w.verificationStatus)}">${verificationStatusLabel(w.verificationStatus)}</span></td><td>${federationWorkerStatus(w)}</td><td>${workloadFor(w)}</td><td>★ ${Number(w.rating||0).toFixed(1)}</td><td>${b?b.id:"—"}</td><td>${getWorkerInsurance(w.id)?.insuranceStatus||w.insuranceStatus||"NOT_ENROLLED"}</td></tr>`;}
function federationOverview(e){const m=federationOperationalMetrics(),demand=federationDemandAnalytics(),alerts=federationOperationalAlerts(),caps=cooperativeCapacityMatrix();e.innerHTML=`<div class="welcome"><div><span class="eyebrow">FEDERATION OPERATIONS</span><h2>Cooperative Federation Administration</h2><p>One shared operational view across ${m.coops.length} cooperative societies. All figures are derived from centralized demo state.</p></div><span class="status-pill blue">Shared federation state</span></div><div class="kpi-grid">${kpi("Total Workers",m.workers.length,"Federation workforce")} ${kpi("Verified Workers",m.verified.length,"Eligible for matching")} ${kpi("Pending Verification",m.pendingVerification.length,"Requires attention")} ${kpi("Available Workers",m.available.length,"Verified + online")} ${kpi("Active Bookings",m.activeBookings.length,"Current services")} ${kpi("Pending Requests",m.bookings.filter(b=>b.status===BOOKING_STATUSES.REQUESTED||b.status===BOOKING_STATUSES.ASSIGNMENT_PENDING).length,"Awaiting assignment")} ${kpi("Completed Services",m.completed.length,"Central history")} ${kpi("Open Complaints",m.openComplaints.length,"Operational cases")} ${kpi("Cooperatives",m.coops.length,"Federation scope")} ${kpi("Capacity Gap",demand.supplyDemandGap,"Rule-based demo signal")}</div><div class="dashboard-grid"><section class="booking-panel"><div class="panel-head"><div><span class="eyebrow">OPERATIONAL ALERTS</span><h3>Federation Alerts</h3></div><button class="btn btn-outline" onclick="renderView('crossRequests')">Cross-Cooperative Support</button></div>${alerts.slice(0,6).map(a=>`<div class="match-row"><div><strong>${escHtml(a.title)}</strong><small>${escHtml(a.message)}</small></div><span class="status-pill ${a.severity==='HIGH'?'amber':'blue'}">${a.severity}</span></div>`).join('')||emptyState('No alerts','No rule-based operational alerts right now.')}</section><section class="booking-panel"><div class="panel-head"><div><span class="eyebrow">SERVICE OPERATIONS</span><h3>Recent requests</h3></div><button class="btn btn-outline" onclick="renderView('requests')">View all</button></div>${m.bookings.slice().sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt))).slice(0,4).map(b=>`<div class="mini-row"><div><b>${b.id}</b><small>${SERVICES.find(s=>s.id===b.service)?.name||b.service} · ${b.location||'Pune'}</small></div><span class="status-pill ${statusClass(b.status)}">${bookingStatusLabel(b.status)}</span></div>`).join('')||emptyState('No requests','New customer requests appear here.')}</section></div><section class="booking-panel"><div class="panel-head"><div><span class="eyebrow">CROSS-COOPERATIVE CAPACITY</span><h3>Cooperative Capacity</h3><small>Calculated from verified workforce, active jobs and shared demand.</small></div><button class="btn btn-outline" onclick="renderView('coops')">View full network</button></div>${caps.map(c=>`<div class="match-row"><div><strong>${escHtml(c.name)}</strong><small>${c.availableWorkers} available · ${c.busyWorkers} busy · ${c.activeJobs} active jobs · ${c.demand} active demand</small></div><span class="status-pill ${c.capacityStatus==='OVERLOADED'||c.capacityStatus==='HIGH_DEMAND'?'amber':c.capacityStatus==='ADEQUATE'?'green':'blue'}">${c.capacityStatus}</span></div>`).join('')}</section><section class="booking-panel"><div class="panel-head"><div><span class="eyebrow">SERVICE CATEGORY CAPACITY</span><h3>Federation Capacity Matrix</h3></div></div><div class="table-wrap"><table><thead><tr><th>Service</th>${caps.slice(0,5).map(c=>`<th>${escHtml(c.name.replace('Pune ','').replace(' Cooperative',''))}</th>`).join('')}</tr></thead><tbody>${SERVICES.filter(s=>caps.some(c=>c.serviceDemand?.[s.id]||federationWorkersFor(c.cooperativeId).some(w=>w.service===s.id))).map(s=>`<tr><td><b>${s.name}</b></td>${caps.slice(0,5).map(c=>{const demand=c.serviceDemand?.[s.id]||0,available=federationWorkersFor(c.cooperativeId).filter(w=>w.service===s.id&&w.verificationStatus==='VERIFIED'&&w.active!==false&&!w.suspended&&w.online!==false).length,level=demand>available?'HIGH DEMAND':available>=demand+2?'ADEQUATE':(demand||available)?'LIMITED':'—';return `<td><span class="status-pill ${level==='HIGH DEMAND'?'amber':level==='ADEQUATE'?'green':'blue'}">${level}</span><small>${demand} demand · ${available} available</small></td>`}).join('')}</tr>`).join('')}</tbody></table></div></section>`;}
function federationCoopsView(e){const m=federationOperationalMetrics();e.innerHTML=`<div class="section-heading compact-head"><div><span class="eyebrow">COOPERATIVE NETWORK</span><h2>Cooperatives</h2></div><input class="filter-input" id="coopSearch" placeholder="Search cooperative…"></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Cooperative</th><th>Area</th><th>Workers</th><th>Verified</th><th>Available</th><th>Active Jobs</th><th>Completed</th><th>Categories</th><th>Status</th></tr></thead><tbody id="coopRows">${m.coops.map(c=>cooperativeAdminRow(c,m)).join("")}</tbody></table></div>`;setTimeout(()=>{const x=$("#coopSearch");if(x)x.oninput=()=>{const q=x.value.toLowerCase();$("#coopRows").innerHTML=m.coops.filter(c=>c.name.toLowerCase().includes(q)||c.id.toLowerCase().includes(q)).map(c=>cooperativeAdminRow(c,m)).join("")||`<tr><td colspan="10">No cooperatives found.</td></tr>`;}},0);}
function cooperativeAdminRow(c,m){const ws=m.workers.filter(w=>w.cooperativeId===c.id),bs=m.bookings.filter(b=>b.cooperativeId===c.id),verified=ws.filter(w=>w.verificationStatus==="VERIFIED"),available=verified.filter(w=>w.online!==false&&w.active!==false&&!w.suspended),active=bs.filter(isFederationActiveBooking),completed=bs.filter(b=>b.status===BOOKING_STATUSES.COMPLETED),cats=[...new Set(ws.map(w=>SERVICES.find(s=>s.id===w.service)?.name||w.skill).filter(Boolean))];return `<tr><td>${c.id}</td><td><b>${c.name}</b></td><td>${c.area||"Pune"}</td><td>${ws.length}</td><td>${verified.length}</td><td>${available.length}</td><td>${active.length}</td><td>${completed.length}</td><td>${cats.join(", ")||"—"}</td><td><span class="status-pill ${c.active===false?'red':'green'}">${c.active===false?'INACTIVE':'ACTIVE'}</span></td></tr>`;}
function federationWorkersView(e){const ws=federationWorkers();e.innerHTML=`<div class="section-heading compact-head"><div><span class="eyebrow">WORKFORCE MANAGEMENT</span><h2>Workers</h2></div><div class="filter-bar"><input class="filter-input" id="workerSearch" placeholder="Search worker…"><select id="workerVerificationFilter"><option value="">All verification</option><option>VERIFIED</option><option>PENDING</option><option>TEST_SCHEDULED</option><option>TEST_ATTENDED</option><option>FAILED</option><option>SUSPENDED</option></select><select id="workerAvailabilityFilter"><option value="">All availability</option><option value="Available">Available</option><option value="Busy">Busy</option><option value="Offline">Offline</option></select></div></div><div class="table-wrap"><table><thead><tr><th>Employee ID</th><th>Worker</th><th>Skill</th><th>Cooperative</th><th>Verification</th><th>Availability</th><th>Workload</th><th>Rating</th><th>Active Booking</th><th>Insurance</th></tr></thead><tbody id="workerRows">${ws.map(federationWorkerRow).join("")}</tbody></table></div>`;const apply=()=>{const q=$("#workerSearch").value.toLowerCase(),vf=$("#workerVerificationFilter").value,af=$("#workerAvailabilityFilter").value;$("#workerRows").innerHTML=ws.filter(w=>(!q||w.name.toLowerCase().includes(q)||w.id.toLowerCase().includes(q)||String(w.skill).toLowerCase().includes(q))&&(!vf||w.verificationStatus===vf)&&(!af||federationWorkerStatus(w)===af)).map(federationWorkerRow).join("")||`<tr><td colspan="10">No workers match the selected filters.</td></tr>`};setTimeout(()=>["#workerSearch","#workerVerificationFilter","#workerAvailabilityFilter"].forEach(sel=>$(sel)?.addEventListener("input",apply)),0);}
function federationRequestsView(e,mode="all"){const bs=federationBookings().filter(b=>{if(mode==="active")return isFederationActiveBooking(b);if(mode==="pending")return b.status===BOOKING_STATUSES.REQUESTED||b.status===BOOKING_STATUSES.ASSIGNMENT_PENDING;if(mode==="completed")return b.status===BOOKING_STATUSES.COMPLETED;if(mode==="cancelled")return b.status===BOOKING_STATUSES.CANCELLED;return true;});e.innerHTML=`<div class="section-heading compact-head"><div><span class="eyebrow">SERVICE REQUESTS</span><h2>${mode==="all"?"All Requests":mode[0].toUpperCase()+mode.slice(1)}</h2></div><div class="filter-bar"><select id="requestStatus"><option value="">All statuses</option>${Object.values(BOOKING_STATUSES).map(x=>`<option>${x}</option>`).join("")}</select><select id="requestService"><option value="">All services</option>${SERVICES.map(s=>`<option value="${s.id}">${s.name}</option>`).join("")}</select></div></div><div class="booking-list" id="requestList">${bs.map(federationAdminRequestPanel).join("")||emptyState("No service requests","Customer bookings within this federation will appear here.")}</div>`;const apply=()=>{const st=$("#requestStatus").value,sv=$("#requestService").value;$("#requestList").innerHTML=bs.filter(b=>(!st||b.status===st)&&(!sv||b.service===sv)).map(federationAdminRequestPanel).join("")||emptyState("No matching requests","Adjust the filters.")};setTimeout(()=>["#requestStatus","#requestService"].forEach(sel=>$(sel)?.addEventListener("change",apply)),0);}
function federationAssignmentsView(e){const bs=federationBookings();e.innerHTML=`<div class="section-heading compact-head"><div><span class="eyebrow">ASSIGNMENT CONTROL</span><h2>Assignments & Reassignment</h2></div><span class="status-pill blue">Rule-based recommendations</span></div>${bs.map(b=>federationAdminRequestPanel(b)).join("")||emptyState("No assignments","Assignments will appear when requests are processed.")}`;}
function federationVerificationView(e){const ws=federationWorkers(),pending=ws.filter(w=>w.verificationStatus!=="VERIFIED");e.innerHTML=`<div class="welcome"><div><span class="eyebrow">VERIFICATION ADMINISTRATION</span><h2>Offline Worker Verification</h2><p>Federation administration records physical-test attendance and explicit PASS/FAIL results. The test itself is not conducted online.</p></div><span class="status-pill blue">Offline process</span></div><div class="kpi-grid">${kpi("Pending",ws.filter(w=>w.verificationStatus==="PENDING").length,"Not yet scheduled")} ${kpi("Scheduled",ws.filter(w=>w.verificationStatus==="TEST_SCHEDULED").length,"Appointment booked")} ${kpi("Attended",ws.filter(w=>w.verificationStatus==="TEST_ATTENDED").length,"Result pending")} ${kpi("Verified",ws.filter(w=>w.verificationStatus==="VERIFIED").length,"Eligible for matching")} ${kpi("Failed",ws.filter(w=>w.verificationStatus==="FAILED").length,"Not eligible")}</div><div class="booking-list">${pending.map(w=>workerVerificationCard(w,true)).join("")||emptyState("No verification cases","All workers in this federation are currently verified.")}</div>`;}
function federationAvailabilityView(e){const ws=federationWorkers();e.innerHTML=`<div class="section-heading compact-head"><div><span class="eyebrow">WORKFORCE AVAILABILITY</span><h2>Availability</h2></div><div class="filter-bar"><select id="availabilityCoop"><option value="">All cooperatives</option>${federationCoops().map(c=>`<option value="${c.id}">${c.name}</option>`).join("")}</select><select id="availabilityState"><option value="">All states</option><option>Available</option><option>Busy</option><option>Offline</option></select></div></div><div class="table-wrap"><table><thead><tr><th>Worker</th><th>Cooperative</th><th>Skill</th><th>Area</th><th>State</th><th>Workload</th><th>Verification</th></tr></thead><tbody id="availabilityRows">${ws.map(w=>`<tr><td>${w.name}</td><td>${getCooperativeById(w.cooperativeId)?.name||"—"}</td><td>${w.skill}</td><td>${w.serviceAreas?.join(", ")||w.area||"—"}</td><td><span class="status-pill ${federationWorkerStatus(w)==="Available"?'green':federationWorkerStatus(w)==="Busy"?'amber':'blue'}">${federationWorkerStatus(w)}</span></td><td>${workloadFor(w)}</td><td>${verificationStatusLabel(w.verificationStatus)}</td></tr>`).join("")}</tbody></table></div>`;const apply=()=>{const c=$("#availabilityCoop").value,a=$("#availabilityState").value;$("#availabilityRows").innerHTML=ws.filter(w=>(!c||w.cooperativeId===c)&&(!a||federationWorkerStatus(w)===a)).map(w=>`<tr><td>${w.name}</td><td>${getCooperativeById(w.cooperativeId)?.name||"—"}</td><td>${w.skill}</td><td>${w.serviceAreas?.join(", ")||w.area||"—"}</td><td>${federationWorkerStatus(w)}</td><td>${workloadFor(w)}</td><td>${verificationStatusLabel(w.verificationStatus)}</td></tr>`).join("")};setTimeout(()=>["#availabilityCoop","#availabilityState"].forEach(sel=>$(sel)?.addEventListener("change",apply)),0);}
function federationOngoingView(e){const bs=federationBookings().filter(isFederationActiveBooking);e.innerHTML=`<div class="section-heading compact-head"><div><span class="eyebrow">LIVE OPERATIONS</span><h2>Ongoing Services</h2></div><span class="status-pill green">Shared booking state</span></div><div class="booking-list">${bs.map(b=>bookingPanel(b)).join("")||emptyState("No ongoing services","Active bookings will appear here as workers progress through the lifecycle.")}</div>`;}
function federationComplaintsView(e){const state=getState(),bs=federationBookings(),cs=state.complaints.filter(c=>bs.some(b=>b.id===c.bookingId));e.innerHTML=`<div class="section-heading compact-head"><div><span class="eyebrow">CASE MANAGEMENT</span><h2>Complaints & Escalations</h2></div><span class="status-pill amber">Federation scope</span></div><div class="booking-list">${cs.map(c=>complaintPanel(c)).join("")||emptyState("No complaints","Customer complaints in this federation will appear here.")}</div>`;}
function complaintPanel(c){const state=getState(),customer=getCustomerById(c.customerId),w=getWorkerById(c.workerId);return `<article class="booking-panel"><div class="panel-head"><div><span class="status-pill ${c.status==='RESOLVED'||c.status==='CLOSED'?'green':c.status==='ESCALATED'?'red':'amber'}">${c.status}</span><h3>${c.id}</h3><small>${c.bookingId} · ${c.category||"Operational"} · ${c.priority||"MEDIUM"}</small></div></div><div class="panel-grid"><span>Customer <b>${customer?.name||"—"}</b></span><span>Worker <b>${w?.name||"—"}</b></span><span>Created <b>${formatDate(String(c.createdAt||"").slice(0,10))}</b></span><span>Description <b>${c.description||"—"}</b></span></div><p><b>Administrative remarks:</b> ${c.adminRemarks||"—"}</p><div class="panel-actions"><select id="complaint-status-${c.id}">${COMPLAINT_STATUSES.map(s=>`<option ${s===c.status?'selected':''}>${s}</option>`).join("")}</select><button class="btn btn-primary" onclick="updateFederationComplaint('${c.id}')">Update</button><button class="btn btn-outline" onclick="escalateFederationComplaint('${c.id}')">Escalate</button></div>${state.escalations.filter(x=>x.complaintId===c.id).map(x=>`<div class="estimate-mini">Escalation ${x.id} · ${x.status} · sent to Platform Admin</div>`).join("")}</article>`;}
function updateFederationComplaint(id){if(role!=="federationAdmin")return;const complaint=getState().complaints.find(x=>x.id===id);if(!complaint||!canResolveComplaint(currentUser(),complaint))return toast("You are not authorized to update this complaint.","error");const st=$("#complaint-status-"+id)?.value;const c=federationComplaintUpdate(id,st,`Updated by Federation Administration on ${formatDateTimeLocalized(new Date(), {dateStyle:"medium", timeStyle:"short"})}`,currentUser()?.id);if(c){toast(`Complaint ${id} updated to ${st}.`);renderView("complaints");}}
function escalateFederationComplaint(id){if(role!=="federationAdmin")return;const esc=escalateComplaint(id,"Requires platform-level administrative review.",currentUser()?.id);if(esc){toast(`Complaint ${id} escalated to Platform Admin.` ,"info");renderView("complaints");}}
function federationWelfareView(e){const ws=federationWorkers(),insured=ws.filter(w=>getWorkerInsurance(w.id)?.insuranceStatus==="ACTIVE"),pending=ws.filter(w=>getWorkerInsurance(w.id)?.insuranceStatus==="PENDING"),expired=ws.filter(w=>getWorkerInsurance(w.id)?.insuranceStatus==="EXPIRED"),none=ws.filter(w=>getWorkerInsurance(w.id)?.insuranceStatus==="NOT_ENROLLED");e.innerHTML=`<div class="kpi-grid">${kpi("Insured",insured.length,"Active demo coverage")} ${kpi("Pending Insurance",pending.length,"Enrollment processing")} ${kpi("Expired",expired.length,"Renewal attention")} ${kpi("No Coverage",none.length,"Not enrolled")} ${kpi("Training Records",ws.filter(w=>getWorkerWelfare(w.id)?.training?.completed?.length).length,"Workers with completed training")}</div><div class="table-wrap"><table><thead><tr><th>Worker</th><th>Cooperative</th><th>Insurance</th><th>Membership</th><th>Training</th></tr></thead><tbody>${ws.map(w=>{const i=getWorkerInsurance(w.id),wf=getWorkerWelfare(w.id);return `<tr><td>${w.name}</td><td>${getCooperativeById(w.cooperativeId)?.name||"—"}</td><td>${i?.insuranceStatus||"NOT_ENROLLED"}</td><td>${wf?.membershipStatus||"—"}</td><td>${wf?.training?.completed?.length||0} completed</td></tr>`}).join("")}</tbody></table></div>`;}
function federationPerformanceView(e){const m=federationOperationalMetrics(),util=m.workers.length?m.workers.reduce((n,w)=>n+Math.min(1,workloadFor(w)/2),0)/m.workers.length*100:0;const byCoop=m.coops.map(c=>{const ws=m.workers.filter(w=>w.cooperativeId===c.id),bs=m.bookings.filter(b=>b.cooperativeId===c.id);return {c,workers:ws.length,active:ws.filter(w=>w.online!==false&&w.verificationStatus==="VERIFIED"&&w.active!==false&&!w.suspended).length,completed:bs.filter(b=>b.status===BOOKING_STATUSES.COMPLETED).length,bookings:bs.length};});e.innerHTML=`<div class="kpi-grid">${kpi("Completion Rate",m.completionRate.toFixed(1)+"%","Completed / total")} ${kpi("Cancellation Rate",m.cancellationRate.toFixed(1)+"%","Cancelled / total")} ${kpi("Average Rating",m.avgRating.toFixed(2),"Worker ratings")} ${kpi("Active Jobs",m.activeBookings.length,"Current operations")} ${kpi("Worker Utilization",util.toFixed(1)+"%","Demo workload indicator")} ${kpi("Complaints Resolved",m.complaints.filter(c=>["RESOLVED","CLOSED"].includes(c.status)).length,"Federation cases")}</div><div class="table-wrap"><table><thead><tr><th>Cooperative</th><th>Bookings</th><th>Completed</th><th>Active Workers</th><th>Total Workers</th></tr></thead><tbody>${byCoop.map(x=>`<tr><td>${x.c.name}</td><td>${x.bookings}</td><td>${x.completed}</td><td>${x.active}</td><td>${x.workers}</td></tr>`).join("")}</tbody></table></div>`;}

function federationMapView(e){e.innerHTML=`<div class="welcome"><div><span class="eyebrow">FEDERATION MAP</span><h2>Service & Capacity Map</h2><p>Approximate demo locations only. Worker home addresses and private GPS coordinates are never shown.</p></div><span class="status-pill blue">Leaflet + OpenStreetMap</span></div><div id="federationMap" class="federation-map" aria-label="Federation service area map"></div><div class="map-legend"><span>🔵 Service request</span><span>🟢 Verified worker area</span><span>🟠 Demand area</span></div>`;setTimeout(()=>{const el=$("#federationMap");if(!el||typeof L==="undefined")return;const map=L.map(el).setView([18.5204,73.8567],12);L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",{attribution:"© OpenStreetMap contributors"}).addTo(map);const bs=federationBookings(),ws=federationWorkers();bs.forEach(b=>{const c=bookingCoordinates(b);L.circleMarker([c.lat,c.lng],{radius:8}).addTo(map).bindPopup(`<b>${b.id}</b><br>${SERVICES.find(s=>s.id===b.service)?.name||b.service}<br>${b.location||"Pune"}`)});[...new Map(ws.filter(w=>w.verificationStatus==="VERIFIED").map(w=>[w.area,w])).values()].forEach(w=>{const c=areaCoordinates(w.area||w.serviceAreas?.[0]||"Pune");if(c)L.circleMarker([c[0],c[1]],{radius:7}).addTo(map).bindPopup(`<b>${w.area||"Pune"}</b><br>Verified worker service area`) });federationCoops().forEach(c=>{const co=areaCoordinates(c.area||"Pune");if(co)L.marker([co[0],co[1]]).addTo(map).bindPopup(`<b>${c.name}</b><br>Cooperative service area`)});map.invalidateSize();},50);}
function federationCrossRequestsView(e){
 const requests=getState().assistanceRequests.filter(r=>r.status!=="CANCELLED"),bs=getState().bookings;
 e.innerHTML=`<div class="welcome"><div><span class="eyebrow">FEDERATION SUPPORT</span><h2>Cross-Cooperative Requests</h2><p>Coordinate verified workforce capacity across cooperative societies when local capacity is insufficient.</p></div><span class="status-pill blue">Shared federation state</span></div>${requests.map(r=>{const b=bs.find(x=>x.id===r.bookingId),reqCoop=getCooperativeById(r.requestingCooperativeId),candidates=getAssistanceCandidates(r.id);return `<article class="booking-panel cross-request-card"><div class="panel-head"><div><span class="status-pill ${r.status==='ACCEPTED'?'green':'amber'}">${r.status}</span><h3>${r.id}</h3><small>${b?.id||r.bookingId} · ${SERVICES.find(s=>s.id===r.serviceCategory)?.name||r.serviceCategory} · ${formatDate(b?.date)} ${b?.time||''}</small></div><span class="status-pill blue">${candidates.length} eligible support worker${candidates.length===1?'':'s'}</span></div><div class="panel-grid"><span>Requesting cooperative <b>${reqCoop?.name||r.requestingCooperativeId||'—'}</b></span><span>Area <b>${escHtml(r.area)}</b></span><span>Reason <b>${escHtml(r.reason)}</b></span><span>Selected <b>${r.selectedWorkerId||'—'}</b></span></div>${candidates.length?`<div class="match-ranking"><h4>Eligible support workers</h4>${candidates.slice(0,5).map((m,i)=>`<div class="match-row"><div><strong>#${i+1} ${m.worker.name}</strong><small>${getCooperativeById(m.worker.cooperativeId)?.name||'Other cooperative'} · ${m.worker.skill} · ${m.eta.label} · ★ ${Number(m.worker.rating||0).toFixed(1)}</small></div><b>${m.score}%</b><button class="text-link" onclick="showMatchExplanation('${b.id}','${m.workerId}')">Why?</button><button class="btn btn-primary btn-sm" onclick="selectFederationSupport('${r.id}','${m.workerId}')">Select</button></div>`).join('')}</div>`:emptyState('No eligible support worker','All other cooperatives are currently unable to support this request.')}</article>`}).join('')||emptyState('No cross-cooperative requests','Requests appear when local capacity cannot meet demand.')}`;
}
function federationAuditView(e){const logs=getState().auditLog.slice().sort((a,b)=>String(b.timestamp).localeCompare(String(a.timestamp)));e.innerHTML=`<div class="welcome"><div><span class="eyebrow">ACCOUNTABILITY</span><h2>Audit Activity</h2><p>Demo audit trail for important federation operational actions. This is not production security logging.</p></div><span class="status-pill blue">${logs.length} events</span></div><div class="table-wrap"><table><thead><tr><th>Time</th><th>Action</th><th>Actor</th><th>Target</th><th>Description</th></tr></thead><tbody>${logs.map(a=>`<tr><td>${formatDateTimeLocalized(a.timestamp, {dateStyle:"medium", timeStyle:"short"})}</td><td><span class="status-pill blue">${a.action}</span></td><td>${escHtml(a.actor||'—')}</td><td>${escHtml(a.target||'—')}</td><td>${escHtml(a.description||'')}</td></tr>`).join('')||`<tr><td colspan="5">No audit events recorded yet.</td></tr>`}</tbody></table></div>`;}
function federationCapacityView(e){const rows=cooperativeCapacityMatrix(),services=SERVICES.filter(s=>rows.some(c=>c.serviceDemand?.[s.id]||federationWorkersFor(c.cooperativeId).some(w=>w.service===s.id)));e.innerHTML=`<section class="booking-panel"><div class="panel-head"><div><span class="eyebrow">CAPACITY MATRIX</span><h3>Service Category Capacity</h3><small>Calculated from verified workers, current jobs and shared booking demand.</small></div></div><div class="table-wrap"><table><thead><tr><th>Service</th>${rows.map(c=>`<th>${escHtml(c.name.replace('Pune ','').replace(' Cooperative',''))}</th>`).join('')}</tr></thead><tbody>${services.map(s=>`<tr><td><b>${s.name}</b></td>${rows.map(c=>{const demand=c.serviceDemand?.[s.id]||0,workers=federationWorkersFor(c.cooperativeId).filter(w=>w.service===s.id&&w.verificationStatus==='VERIFIED'&&w.active!==false&&!w.suspended&&w.online!==false).length,level=demand>workers?'HIGH DEMAND':workers>=demand+2?'ADEQUATE':(demand||workers)?'LIMITED':'—';return `<td><span class="status-pill ${level==='HIGH DEMAND'?'amber':level==='ADEQUATE'?'green':'blue'}">${level}</span><small>${demand} demand · ${workers} available</small></td>`}).join('')}</tr>`).join('')}</tbody></table></div></section>`;}
function federationView(v,e){const admin=currentFederationAdmin();if(!admin){e.innerHTML=emptyState("Federation scope unavailable","The demo federation administrator identity is missing.");return;}if(v==="overview")federationOverview(e);else if(v==="coops")federationCoopsView(e);else if(v==="workers")federationWorkersView(e);else if(v==="requests")federationRequestsView(e);else if(v==="assignments")federationAssignmentsView(e);else if(v==="availability")federationAvailabilityView(e);else if(v==="map")federationMapView(e);else if(v==="verification")federationVerificationView(e);else if(v==="ongoing")federationOngoingView(e);else if(v==="complaints")federationComplaintsView(e);else if(v==="welfare")federationWelfareView(e);else if(v==="performance")federationPerformanceView(e);else if(v==="demand")window.federationDemandView(e);else if(v==="crossRequests")federationCrossRequestsView(e);else if(v==="audit")federationAuditView(e);else federationOverview(e);}
function renderFederationAdmin(v,e){federationView(v,e)}

function renderAdmin(v,e){const state=getState(),workers=state.workers,bookings=state.bookings,complaints=state.complaints||[],coops=state.cooperatives,feds=state.federations;if(v==="overview"){e.innerHTML=`<div class="welcome"><div><span class="eyebrow">PLATFORM ADMINISTRATION</span><h2>Platform Admin</h2><p>System-level demo administration remains separate from federation operations.</p></div><span class="status-pill blue">Platform scope</span></div><div class="kpi-grid">${kpi("Workers",workers.length,"Central state")} ${kpi("Customers",state.customers.length,"Central state")} ${kpi("Bookings",bookings.length,"Central state")} ${kpi("Cooperatives",coops.length,"Federation network")} ${kpi("Federations",feds.length,"Platform scope")} ${kpi("Open Complaints",complaints.filter(c=>["OPEN","UNDER_REVIEW","ESCALATED"].includes(c.status)).length,"Operational cases")}</div><div class="booking-panel"><h3>Administration boundary</h3><p>Platform Admin can view broader demo system information, while federation administration remains responsible for federation/cooperative operations.</p></div>`}else if(v==="workers"){e.innerHTML=`<div class="table-wrap"><table><thead><tr><th>Worker</th><th>Skill</th><th>Cooperative</th><th>Verification</th><th>Insurance</th><th>Status</th></tr></thead><tbody>${workers.map(w=>`<tr><td>${escHtml(w.name)}</td><td>${escHtml(w.skill)}</td><td>${getCooperativeById(w.cooperativeId)?.name||"—"}</td><td>${verificationStatusLabel(w.verificationStatus)}</td><td>${getWorkerInsurance(w.id)?.insuranceStatus||"NOT_ENROLLED"}</td><td>${w.suspended?"Suspended":w.active===false?"Inactive":"Active"}</td></tr>`).join("")}</tbody></table></div>`}else if(v==="customers"){e.innerHTML=`<div class="table-wrap"><table><thead><tr><th>Customer</th><th>ID</th><th>Area</th><th>Bookings</th></tr></thead><tbody>${state.customers.map(c=>`<tr><td>${escHtml(c.name)}</td><td>${c.id}</td><td>${c.area||"Pune"}</td><td>${bookings.filter(b=>b.customerId===c.id).length}</td></tr>`).join("")}</tbody></table></div>`}else if(v==="coops"){e.innerHTML=`<div class="table-wrap"><table><thead><tr><th>ID</th><th>Cooperative</th><th>Federation</th><th>Workers</th><th>Status</th></tr></thead><tbody>${coops.map(c=>`<tr><td>${c.id}</td><td>${escHtml(c.name)}</td><td>${getFederationById(c.federationId)?.name||"—"}</td><td>${workers.filter(w=>w.cooperativeId===c.id).length}</td><td>${c.active===false?"INACTIVE":"ACTIVE"}</td></tr>`).join("")}</tbody></table></div>`}else if(v==="federations"){e.innerHTML=`<div class="table-wrap"><table><thead><tr><th>ID</th><th>Federation</th><th>Area</th><th>Cooperatives</th><th>Workers</th></tr></thead><tbody>${feds.map(f=>`<tr><td>${f.id}</td><td>${f.name}</td><td>${f.area||"—"}</td><td>${coops.filter(c=>c.federationId===f.id).length}</td><td>${workers.filter(w=>coops.some(c=>c.id===w.cooperativeId&&c.federationId===f.id)).length}</td></tr>`).join("")}</tbody></table></div>`}else if(v==="requests"||v==="assignments"){e.innerHTML=`<div class="booking-list">${bookings.map(bookingPanel).join("")||emptyState("No bookings","No shared booking records.")}</div>`}else if(v==="complaints"){e.innerHTML=`<div class="booking-list">${complaints.map(complaintPanel).join("")||emptyState("No complaints","No complaint records.")}</div>`}else if(v==="payments"){e.innerHTML=`<div class="table-wrap"><table><thead><tr><th>Booking</th><th>Type</th><th>Amount</th><th>Status</th></tr></thead><tbody>${state.payments.map(p=>`<tr><td>${p.bookingId}</td><td>${p.type}</td><td>₹${Number(p.amount||0).toLocaleString()}</td><td>${p.status}${p.simulated?" · Demo":""}</td></tr>`).join("")}</tbody></table></div>`}else if(v==="security"){location.href="security.html"}else e.innerHTML=emptyState("Platform administration","This prototype keeps platform-level configuration intentionally limited. Operational federation functions live in Federation Administration.")}

function profilePage(u){
 const isWorkerProfile=!!u?.verificationStatus||u?.role==="Worker";
 if(!isWorkerProfile)return `<div class="profile-page"><div class="profile-head"><span class="avatar huge">${u.initials||"U"}</span><div><span class="eyebrow">${u.role||"Profile"}</span><h2>${u.name||"User"}</h2><p>Demo profile · Pune service platform</p></div></div><div class="profile-grid"><div><h3>Account information</h3><p><b>Role:</b> ${u.role||"—"}</p><p><b>Location:</b> Pune service area</p></div><div class="privacy-note"><b>Privacy:</b> sensitive credentials, government IDs, bank details and private documents are intentionally not displayed. LocalStorage is not production security.</div></div></div>`;
 const status=u.verificationStatus,details=u.verificationDetails||{};
 return `<div class="profile-page"><div class="profile-head"><span class="avatar huge">${u.initials||u.avatar||"WK"}</span><div><span class="eyebrow">WORKER PROFILE</span><h2>${u.name}</h2><p>${u.skill||"Worker"} · ${u.experience||u.exp||0} years experience</p><span class="status-pill ${verificationStatusClass(status)}">${status==="VERIFIED"?"✓ ":""}${verificationStatusLabel(status)}</span></div></div><div class="profile-grid"><div><h3>Professional information</h3><p><b>Skills:</b> ${(u.skills||[u.skill]).filter(Boolean).join(", ")}</p><p><b>Service areas:</b> ${(u.serviceAreas||[]).join(", ")||"—"}</p><p><b>Cooperative:</b> ${getCooperativeById(u.cooperativeId)?.name||u.coop||"—"}</p><p><b>Phone:</b> ${u.phone||"—"}</p><p><b>Email:</b> ${u.email||"—"}</p></div><div><h3>Verification</h3><p><b>Status:</b> ${verificationStatusLabel(status)}</p>${details.verifiedSkills?.length?`<p><b>Verified skills:</b> ${details.verifiedSkills.join(", ")}</p>`:""}${details.testDate?`<p><b>Test date:</b> ${formatDate(details.testDate)}</p>`:""}${status!=="VERIFIED"?`<p class="privacy-note">You must pass an offline skill verification test before becoming eligible for verified service assignments.</p><button class="btn btn-primary" onclick="renderView('verification')">${verificationAppointmentFor(u.id)?"View Test Appointment":"Schedule Offline Test"}</button>`:`<div class="estimate-mini">✓ You are now eligible for verified-worker matching.</div>`}</div></div><div class="privacy-note"><b>Prototype privacy:</b> sensitive credentials, government IDs, bank details and private documents are not displayed. LocalStorage is not production security.</div></div>`;
}

