function p9t(key){const lang=getState().language||"en";const dict={en:{notifications:"Notifications",all:"All",unread:"Unread",markAll:"Mark all as read",open:"Open",markRead:"Mark as read",caught:"You're all caught up",noNotifications:"No notifications are available right now.",noUnread:"No unread notifications.",centerText:"Relevant service updates from your shared Co-opGig state."},mr:{notifications:"सूचना",all:"सर्व",unread:"वाचलेल्या नाहीत",markAll:"सर्व वाचले म्हणून चिन्हांकित करा",open:"उघडा",markRead:"वाचले म्हणून चिन्हांकित करा",caught:"तुम्ही अद्ययावत आहात",noNotifications:"सध्या कोणत्याही सूचना नाहीत.",noUnread:"वाचलेल्या नसलेल्या सूचना नाहीत.",centerText:"तुमच्या सामायिक Co-opGig स्थितीतील संबंधित सेवा अद्यतने."},hi:{notifications:"सूचनाएँ",all:"सभी",unread:"अपठित",markAll:"सभी को पढ़ा हुआ करें",open:"खोलें",markRead:"पढ़ा हुआ करें",caught:"आप पूरी तरह अपडेट हैं",noNotifications:"अभी कोई सूचना उपलब्ध नहीं है।",noUnread:"कोई अपठित सूचना नहीं है।",centerText:"आपकी साझा Co-opGig स्थिति से संबंधित सेवा अपडेट।"},ta:{notifications:"அறிவிப்புகள்",all:"அனைத்தும்",unread:"படிக்காதவை",markAll:"அனைத்தையும் படித்ததாகக் குறிக்கவும்",open:"திறக்கவும்",markRead:"படித்ததாகக் குறிக்கவும்",caught:"நீங்கள் அனைத்தையும் பார்த்துவிட்டீர்கள்",noNotifications:"தற்போது அறிவிப்புகள் எதுவும் இல்லை.",noUnread:"படிக்காத அறிவிப்புகள் இல்லை.",centerText:"உங்கள் பகிரப்பட்ட Co-opGig நிலையிலிருந்து தொடர்புடைய சேவை புதுப்பிப்புகள்."},te:{notifications:"నోటిఫికేషన్లు",all:"అన్నీ",unread:"చదవనివి",markAll:"అన్నింటినీ చదివినట్లు గుర్తించండి",open:"తెరవండి",markRead:"చదివినట్లు గుర్తించండి",caught:"మీరు అన్ని నవీకరణలను చూశారు",noNotifications:"ప్రస్తుతం నోటిఫికేషన్లు ఏవీ లేవు.",noUnread:"చదవని నోటిఫికేషన్లు లేవు.",centerText:"మీ భాగస్వామ్య Co-opGig స్థితి నుండి సంబంధిత సేవా నవీకరణలు."}};return dict[lang]?.[key]||dict.en[key]||key;}
function phase9RoleRecipient(){return currentUser()?.id||null;}
function phase9NotificationDestination(n){
 const type=String(n?.type||"");
 if(role==="customer")return type===NOTIFICATION_TYPES.REVIEW_REQUEST?"reviews":type===NOTIFICATION_TYPES.MESSAGE?"messages":"bookings";
 if(role==="worker")return type===NOTIFICATION_TYPES.REVIEW?"reviews":type===NOTIFICATION_TYPES.MESSAGE?"messages":type.includes("verification")?"verification":"jobs";
 if(role==="federationAdmin")return type.includes("complaint")||type===NOTIFICATION_TYPES.ESCALATION?"complaints":type.includes("capacity")||type.includes("assistance")?"crossRequests":type.includes("verification")?"verification":"overview";
 return type===NOTIFICATION_TYPES.ESCALATION||type.includes("complaint")?"complaints":"overview";
}
function phase9NotificationView(e){
 const ns=getUserNotifications(phase9RoleRecipient()),unread=ns.filter(n=>!n.read).length;
 e.innerHTML=`<div class="welcome"><div><span class="eyebrow">NOTIFICATION CENTER</span><h2>${p9t("notifications")}</h2><p>${p9t("centerText")}</p></div><div class="detail-actions"><span class="status-pill ${unread?"amber":"green"}">${unread} unread</span>${unread?`<button class="btn btn-outline" onclick="phase9MarkAllNotificationsRead()">Mark all as read</button>`:""}</div></div><div class="notification-tabs"><button class="active" onclick="phase9RenderNotificationFilter('all')">${p9t("all")}</button><button onclick="phase9RenderNotificationFilter('unread')">${p9t("unread")}</button></div><div id="notificationList">${phase9NotificationListHtml(ns)}</div>`;
}
function phase9NotificationListHtml(ns){if(!ns.length)return emptyState("You're all caught up","No notifications are available right now.");return ns.map(n=>`<article class="notification-card ${n.read?"read":"unread"}"><div class="notification-icon">${n.type===NOTIFICATION_TYPES.MESSAGE?"◌":n.type===NOTIFICATION_TYPES.REVIEW?"★":n.type.includes("assignment")?"↔":n.type.includes("complaint")||n.type===NOTIFICATION_TYPES.ESCALATION?"!":"•"}</div><div class="notification-copy"><div class="notification-head"><b>${escHtml(n.title||"Notification")}</b><small>${formatDateTimeLocalized(n.createdAt, {dateStyle:"medium", timeStyle:"short"})}</small></div><p>${escHtml(n.message||"")}</p><div class="panel-actions"><button class="btn btn-light" onclick="phase9OpenNotification('${n.id}')">${p9t("open")}</button>${!n.read?`<button class="btn btn-outline" onclick="phase9MarkNotificationRead('${n.id}')">${p9t("markRead")}</button>`:""}</div></div></article>`).join("");}
function phase9RenderNotificationFilter(filter){const all=getUserNotifications(phase9RoleRecipient());const ns=filter==="unread"?all.filter(n=>!n.read):all;const el=$("#notificationList");if(el)el.innerHTML=ns.length?phase9NotificationListHtml(ns):emptyState(filter==="unread"?"No unread notifications":"You're all caught up",filter==="unread"?"No unread notifications.":"No notifications are available right now.");}
function phase9OpenNotification(id){const n=getUserNotifications(phase9RoleRecipient()).find(x=>x.id===id);if(!n)return;markNotificationRead(id);renderView(phase9NotificationDestination(n));}
function phase9MarkNotificationRead(id){markNotificationRead(id);renderView("notifications");}
function phase9MarkAllNotificationsRead(){markAllNotificationsRead(phase9RoleRecipient());renderView("notifications");}
function phase9RefreshNotificationUI(){
 const userId=phase9RoleRecipient(),count=getUnreadNotificationCount(userId),navButton=$('#sideNav button[data-view="notifications"]');
 if(navButton){const label=(localizedNavs()[role]||[]).find(x=>x[0]==="notifications")?.[1]||"Notifications";navButton.querySelector("span")?.replaceChildren(document.createTextNode(label+(count?` ${count}`:"")));}
 let head=$("#notificationHeaderBtn");if(!head){const actions=$(".dash-actions");if(actions){head=document.createElement("button");head.id="notificationHeaderBtn";head.className="btn btn-outline notification-header-btn";head.type="button";head.innerHTML=`🔔 <span></span>`;actions.insertBefore(head,actions.firstChild);head.onclick=()=>renderView("notifications");}}
 if(head){head.querySelector("span").textContent=count?`${count} unread`:"Notifications";head.classList.toggle("has-unread",count>0);}
}
const _renderViewPhase9=renderView;
renderView=function(view){_renderViewPhase9(view);phase9RefreshNotificationUI();};
const _initDashPhase9=initDash;
initDash=function(){_initDashPhase9();phase9RefreshNotificationUI();};

function phase9ChatMessagesHtml(id){const messages=getConversationMessages(id);if(!messages.length)return `<div class="chat-msg received">No messages yet. Start the conversation.</div>`;return messages.map(m=>{const mine=[currentUser()?.id,currentWorker()?.id,currentCustomer()?.id].includes(m.senderId);return `<div class="chat-msg ${mine?"sent":"received"}">${escHtml(m.message)}<small>${new Date(m.timestamp).toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"})}${m.read?" · Read":""}</small></div>`}).join("");}
chatMessagesHtml=phase9ChatMessagesHtml;
function openChat(id){const b=getState().bookings.find(x=>x.id===id),w=b&&getBookingWorker(b),c=b&&getCustomerById(b.customerId);if(!b||!w||!phase9CanAccessConversation(id,currentUser()?.id))return toast("This conversation is not available to your account.","error");markConversationRead(id);const otherName=role==="worker"?(c?.name||"Customer"):(w?.name||"Worker");$("#globalModal").classList.remove("hidden");$("#globalModalContent").innerHTML=`<button class="modal-close" onclick="closeGlobal()">×</button><div class="chat-head"><span class="avatar">${w.avatar||"WK"}</span><div><b>Message ${escHtml(otherName)}</b><small>${b.id} · ${w.skill||"Assigned worker"}</small></div><button class="btn btn-outline" onclick="demoCall('${b.id}')">☎ Call</button></div><div class="chat-window">${phase9ChatMessagesHtml(id)}</div><div class="chat-compose"><input id="dashChat2" placeholder="Type a message…" maxlength="500"><button class="btn btn-primary" onclick="sendDashChat('${id}')">Send</button></div><div class="privacy-note">Service conversation only. Private credentials and unnecessary personal information are not shown.</div>`;phase9RefreshNotificationUI();}
function sendDashChat(id){const input=$("#dashChat2"),result=sendMessageForBooking(id,input?.value||"");if(result?.error)return toast(result.error,"error");if(input)input.value="";toast("Message sent.","success");openChat(id);}
function dashSend(){const b=role==="worker"?getBookingsForWorker(worker?.id)[0]:getBookingsForCustomer(currentCustomer()?.id||"c1")[0];const input=$("#dashChat");if(!b||!input?.value.trim())return;const result=sendMessageForBooking(b.id,input.value);if(result?.error)return toast(result.error,"error");input.value="";toast("Message sent.","success");renderView("messages");}
function demoCall(bookingId=null){const b=bookingId?getState().bookings.find(x=>x.id===bookingId):null;if(b&&!phase9CanAccessConversation(b.id,currentUser()?.id))return toast("Call access is limited to the booking participants.","error");$("#globalModal").classList.remove("hidden");$("#globalModalContent").innerHTML=`<button class="modal-close" onclick="closeGlobal()">×</button><div class="call-demo"><div class="call-icon">☎</div><span class="eyebrow">DEMO CALL</span><h2>Demo call initiated</h2><p>No real phone call was placed. This frontend prototype only demonstrates the service communication action.</p>${b?`<div class="info-box"><b>Booking:</b> ${escHtml(b.id)}<br><b>Contact:</b> ${escHtml(getBookingWorker(b)?.name||getCustomerById(b.customerId)?.name||"Service contact")}</div>`:""}<button class="btn btn-primary" onclick="closeGlobal()">Done</button></div>`;}

function customerReviewPanel(b){const w=getBookingWorker(b),existing=getState().reviews.find(r=>r.bookingId===b.id&&r.customerId===currentCustomer()?.id),summary=w?getWorkerReviewSummary(w.id):{rating:0,reviewCount:0};return `<article class="booking-panel"><div class="panel-head"><div><span class="status-pill green">Completed</span><h3>${SERVICES.find(s=>s.id===b.service)?.name||b.service}</h3><small>${b.id} · ${formatDate(b.date)}</small></div><span class="avatar">${w?.avatar||"WK"}</span></div><p>Worker: <b>${w?.name||"—"}</b> · Current rating <b>★ ${summary.rating.toFixed(1)}</b> (${summary.reviewCount})</p>${existing?`<div class="estimate-mini">Your review: <b>${reviewStars(existing.rating)}</b><br>${escHtml(existing.comment||"No written comment.")}</div>`:`<div class="panel-actions"><button class="btn btn-primary" onclick="submitReview('${b.id}')">Rate Worker</button></div>`}</article>`;}
function submitReview(id){if(role!=="customer")return;const check=canReviewBooking(id,currentCustomer()?.id);if(!check.eligible)return toast(check.reason,"info");$("#globalModal").classList.remove("hidden");$("#globalModalContent").innerHTML=`<button class="modal-close" onclick="closeGlobal()">×</button><span class="eyebrow">SERVICE REVIEW</span><h2>How was your service?</h2><div class="rating-picker" role="radiogroup" aria-label="Rating"><button type="button" data-rating="1">☆</button><button type="button" data-rating="2">☆</button><button type="button" data-rating="3">☆</button><button type="button" data-rating="4">☆</button><button type="button" data-rating="5">☆</button></div><p id="ratingHint" class="muted">Select 1 to 5 stars.</p><label>Written review <textarea id="reviewComment" maxlength="500" placeholder="How was the service? (optional)"></textarea></label><div class="step-actions"><button class="btn btn-outline" onclick="closeGlobal()">Cancel</button><button class="btn btn-primary" onclick="saveReview('${id}')">Submit Review</button></div>`;let selected=0;$$('[data-rating]').forEach(btn=>btn.onclick=()=>{selected=Number(btn.dataset.rating);$$('[data-rating]').forEach(x=>x.textContent=Number(x.dataset.rating)<=selected?"★":"☆");$("#ratingHint").textContent=`${selected}/5 stars selected`;});}
function saveReview(id){if(role!=="customer")return;const rating=Number($('[data-rating][data-selected="true"]')?.dataset.rating||0)||$$('[data-rating]').reduce((n,b)=>b.textContent==="★"?n+1:n,0);const result=submitCentralReview(id,rating,$("#reviewComment")?.value||"");if(result?.error)return toast(result.error,"error");closeGlobal();toast("Thank you for reviewing the worker.","success");renderView("reviews");}

/* Phase 9: event-driven booking notifications */


function advanceWorker(id,status){if(role!=="worker")return;const state=getState(),b=state.bookings.find(x=>x.id===id),a=state.assignments.find(x=>x.bookingId===id&&x.workerId===worker?.id&&x.status===ASSIGNMENT_STATUSES.ACCEPTED);if(!b||!a)return;const allowed={[BOOKING_STATUSES.ACCEPTED]:BOOKING_STATUSES.ON_THE_WAY,[BOOKING_STATUSES.ON_THE_WAY]:BOOKING_STATUSES.ARRIVED,[BOOKING_STATUSES.ARRIVED]:BOOKING_STATUSES.INSPECTION,[BOOKING_STATUSES.SERVICE_IN_PROGRESS]:BOOKING_STATUSES.COMPLETED};if(allowed[b.status]!==status)return;setBookingStatus(state,b,status);saveState(state);toast(`Booking ${id}: ${bookingStatusLabel(status)}`);renderView("jobs");}

function phase9PushNotification(state,{recipientId,type,title,message,relatedEntityId=null,bookingId=null,eventKey=null,force=false}={}){if(!recipientId||!message)return null;state.notifications=Array.isArray(state.notifications)?state.notifications:[];const key=eventKey||`${relatedEntityId||bookingId||""}:${type||""}:${recipientId}`;if(!force&&state.notifications.some(n=>phase9NotificationKey(n)===key))return state.notifications.find(n=>phase9NotificationKey(n)===key)||null;const n={id:`notif-${Date.now()}-${state.notifications.length+1}`,recipientId,userId:recipientId,type:type||NOTIFICATION_TYPES.SYSTEM,title:title||"Notification",message,relatedEntityId,bookingId,eventKey:key,createdAt:new Date().toISOString(),read:false};state.notifications.push(n);return n;}
function phase9NotifyBookingEvent(state,b,status){const customerId=phase9CustomerUserId(b.customerId),w=getBookingWorker(b),workerId=w?phase9WorkerUserId(w.id):null;const events={
 [BOOKING_STATUSES.REQUESTED]:[[customerId,"booking","Booking Request","Your service request has been submitted."],[DEMO_USERS.federationAdmin.id,"booking","New Service Request",`New service request ${b.id} requires federation review.`]],
 [BOOKING_STATUSES.ASSIGNED]:[[customerId,"assignment","Worker Assigned",`${w?.name||"A verified worker"} has been assigned to booking ${b.id}.`],[workerId,"assignment","New Assignment",`You have a new assignment ${b.id}. Please review and respond.`]],
 [BOOKING_STATUSES.ACCEPTED]:[[customerId,"accepted","Worker Accepted",`${w?.name||"Your worker"} accepted booking ${b.id}.`]],
 [BOOKING_STATUSES.ON_THE_WAY]:[[customerId,"on_the_way","Worker On The Way",`Your worker is on the way for booking ${b.id}.`]],
 [BOOKING_STATUSES.ARRIVED]:[[customerId,"arrived","Worker Arrived",`Your worker has arrived for booking ${b.id}.`]],
 [BOOKING_STATUSES.INSPECTION]:[[customerId,"inspection","Inspection Started",`Inspection has started for booking ${b.id}.`]],
 [BOOKING_STATUSES.ESTIMATE_PENDING]:[[customerId,"estimate","Estimate Ready",`Your service estimate is ready for booking ${b.id}.`]],
 [BOOKING_STATUSES.CUSTOMER_DECISION]:[[customerId,"estimate","Estimate Ready",`Your service estimate is ready for booking ${b.id}.`]],
 [BOOKING_STATUSES.SERVICE_IN_PROGRESS]:[[customerId,"service_in_progress","Service In Progress",`Service has started for booking ${b.id}.`]],
 [BOOKING_STATUSES.COMPLETED]:[[customerId,"completed","Service Completed",`Service ${b.id} is completed. Please rate your experience.`],[customerId,"review_request","Rate Your Service","Your completed service is ready for review."]],
 [BOOKING_STATUSES.CANCELLED]:[[customerId,"cancellation","Booking Cancelled",`Booking ${b.id} has been cancelled.`],[workerId,"cancellation","Booking Cancelled",`Booking ${b.id} has been cancelled.`],[DEMO_USERS.federationAdmin.id,"cancellation","Booking Cancelled",`Booking ${b.id} was cancelled.`]]
 }[status]||[];events.forEach(([recipientId,type,title,message])=>phase9PushNotification(state,{recipientId,type,title,message,relatedEntityId:b.id,bookingId:b.id,eventKey:`booking-${b.id}-${type}-${recipientId}`}));}
const BOOKING_TRANSITIONS={
 [BOOKING_STATUSES.REQUESTED]:[BOOKING_STATUSES.ASSIGNMENT_PENDING,BOOKING_STATUSES.ASSIGNED,BOOKING_STATUSES.CANCELLED],
 [BOOKING_STATUSES.ASSIGNMENT_PENDING]:[BOOKING_STATUSES.ASSIGNED,BOOKING_STATUSES.CANCELLED],
 [BOOKING_STATUSES.ASSIGNED]:[BOOKING_STATUSES.ACCEPTED,BOOKING_STATUSES.ASSIGNMENT_PENDING,BOOKING_STATUSES.CANCELLED],
 [BOOKING_STATUSES.ACCEPTED]:[BOOKING_STATUSES.ON_THE_WAY,BOOKING_STATUSES.CANCELLED],
 [BOOKING_STATUSES.ON_THE_WAY]:[BOOKING_STATUSES.ARRIVED,BOOKING_STATUSES.CANCELLED],
 [BOOKING_STATUSES.ARRIVED]:[BOOKING_STATUSES.INSPECTION,BOOKING_STATUSES.CANCELLED],
 [BOOKING_STATUSES.INSPECTION]:[BOOKING_STATUSES.ESTIMATE_PENDING,BOOKING_STATUSES.CUSTOMER_DECISION,BOOKING_STATUSES.CANCELLED],
 [BOOKING_STATUSES.ESTIMATE_PENDING]:[BOOKING_STATUSES.CUSTOMER_DECISION,BOOKING_STATUSES.CANCELLED],
 [BOOKING_STATUSES.CUSTOMER_DECISION]:[BOOKING_STATUSES.SERVICE_IN_PROGRESS,BOOKING_STATUSES.CANCELLED],
 [BOOKING_STATUSES.SERVICE_IN_PROGRESS]:[BOOKING_STATUSES.COMPLETED,BOOKING_STATUSES.CANCELLED],
 [BOOKING_STATUSES.COMPLETED]:[],
 [BOOKING_STATUSES.CANCELLED]:[]
};
function canTransitionBooking(from,to){return from===to || (BOOKING_TRANSITIONS[from]||[]).includes(to);}
function setBookingStatus(state,b,status){if(!b||!Object.values(BOOKING_STATUSES).includes(status))return false;const previous=b.status;if(previous===status)return true;if(!canTransitionBooking(previous,status))return false;const now=new Date().toISOString();b.status=status;b.updatedAt=now;if(status===BOOKING_STATUSES.COMPLETED){b.completedAt=now;const a=state.assignments.find(x=>x.bookingId===b.id&&x.workerId===b.primaryWorkerId&&!['REJECTED','CANCELLED'].includes(x.status));if(a){a.status=ASSIGNMENT_STATUSES.COMPLETED;a.completedAt=now}state.invoices=Array.isArray(state.invoices)?state.invoices:[];const estimate=b.estimate||state.estimates.find(x=>x.bookingId===b.id);if(estimate&&!state.invoices.some(i=>i.bookingId===b.id)){state.invoices.push({id:`invoice-${b.id}`,bookingId:b.id,customerId:b.customerId,workerId:b.primaryWorkerId,subtotal:Number(estimate.total||0),inspectionCharge:Number(b.inspectionCharge||0),total:Number(estimate.total||0)+Number(b.inspectionCharge||0),status:'ISSUED',issuedAt:now,simulated:true});}const existing=state.payments.find(p=>p.bookingId===b.id&&p.type==='service');if(existing){existing.status=PAYMENT_STATUSES.PENDING;existing.paidAt=null}else state.payments.push({id:`payment-${b.id}-service`,bookingId:b.id,amount:Number(estimate?.total||0),type:'service',status:PAYMENT_STATUSES.PENDING,simulated:true,createdAt:now});}phase9NotifyBookingEvent(state,b,status);return true;}
function workerDecision(id,decision){if(role!=="worker"||!worker||!["accept","reject"].includes(decision))return;const state=getState(),b=state.bookings.find(x=>x.id===id),a=state.assignments.find(x=>x.bookingId===id&&x.workerId===worker.id&&!['REJECTED','CANCELLED','COMPLETED'].includes(x.status));if(!b||!a||![BOOKING_STATUSES.ASSIGNED,BOOKING_STATUSES.ASSIGNMENT_PENDING].includes(b.status))return toast("This assignment is no longer awaiting your response.","info");const now=new Date().toISOString();if(decision==="accept"){a.status=ASSIGNMENT_STATUSES.ACCEPTED;a.acceptedAt=now;b.primaryWorkerId=worker.id;b.status=BOOKING_STATUSES.ACCEPTED;phase9PushNotification(state,{recipientId:phase9CustomerUserId(b.customerId),type:NOTIFICATION_TYPES.ACCEPTED,title:"Worker Accepted",message:`${worker.name} accepted booking ${b.id}.`,bookingId:b.id,eventKey:`booking-${b.id}-accepted-${phase9CustomerUserId(b.customerId)}`});const assistance=state.assistanceRequests.find(r=>r.bookingId===id&&r.status!=="CANCELLED");if(assistance&&assistance.selectedWorkerId===worker.id){assistance.status="ACCEPTED";assistance.updatedAt=now;}}else{a.status=ASSIGNMENT_STATUSES.REJECTED;a.rejectedAt=now;a.rejectionReason="Worker rejected assignment";b.primaryWorkerId=null;b.status=BOOKING_STATUSES.ASSIGNMENT_PENDING;phase9PushNotification(state,{recipientId:DEMO_USERS.federationAdmin.id,type:NOTIFICATION_TYPES.ASSIGNMENT,title:"Worker Rejected Assignment",message:`${worker.name} rejected assignment ${id}. Reassignment is required.`,bookingId:id,eventKey:`reject-${id}-${worker.id}`});const localCoop=b.originCooperativeId||b.cooperativeId;const localEligible=findEligibleWorkers(b).filter(r=>getWorkerById(r.workerId)?.cooperativeId===localCoop&&r.workerId!==worker.id);if(!localEligible.length)createAssistanceRequest(b.id,`Worker ${worker.name} rejected the assignment and no suitable local replacement is available.`);auditFederationAction("REASSIGN_WORKER",id,`Worker ${worker.id} rejected the assignment; reassignment may be required.`);}b.updatedAt=now;saveState(state);toast(decision==="accept"?"Job accepted.":"Assignment rejected.",decision==="accept"?"success":"info");renderView("jobs");}
function submitEstimate(id){if(role!=="worker")return;const state=getState(),b=state.bookings.find(x=>x.id===id);if(!b||b.primaryWorkerId!==worker?.id||![BOOKING_STATUSES.INSPECTION,BOOKING_STATUSES.ESTIMATE_PENDING].includes(b.status))return toast("This booking is not ready for an estimate.","info");const material=Number($("#estimateMaterial")?.value||0),labour=Number($("#estimateLabour")?.value||0);if(!Number.isFinite(material)||!Number.isFinite(labour)||material<0||labour<0)return toast("Enter valid non-negative estimate values.","error");const now=new Date().toISOString(),estimate={id:`estimate-${id}`,bookingId:id,material,labour,total:material+labour,notes:$("#estimateNotes")?.value.trim()||"",createdAt:now,submittedBy:worker.id};state.estimates=(state.estimates||[]).filter(x=>x.bookingId!==id);state.estimates.push(estimate);b.estimate=estimate;b.status=BOOKING_STATUSES.CUSTOMER_DECISION;b.updatedAt=now;createNotification({recipientId:phase9CustomerUserId(b.customerId),type:NOTIFICATION_TYPES.ESTIMATE,title:"Estimate Ready",message:`Estimate of ₹${estimate.total.toLocaleString()} is ready for your decision.`,bookingId:id,eventKey:`estimate-${id}-${phase9CustomerUserId(b.customerId)}`});saveState(state);closeGlobal();toast("Estimate submitted. Customer decision is now required.");renderView("jobs");}
function customerEstimateDecision(id,decision){if(role!=="customer"||!["accept","decline"].includes(decision))return;const state=getState(),b=state.bookings.find(x=>x.id===id);if(!b||b.customerId!==currentCustomer()?.id||b.status!==BOOKING_STATUSES.CUSTOMER_DECISION||!b.estimate)return toast("This estimate is no longer awaiting your decision.","info");const now=new Date().toISOString();if(decision==="accept"){b.status=BOOKING_STATUSES.SERVICE_IN_PROGRESS;const p=state.payments.find(x=>x.bookingId===id&&x.type==="service");if(p)p.status=PAYMENT_STATUSES.PENDING;else state.payments.push({id:`payment-${id}-service`,bookingId:id,amount:Number(b.estimate.total||0),type:"service",status:PAYMENT_STATUSES.PENDING,simulated:true,createdAt:now});createNotification({recipientId:phase9WorkerUserId(b.primaryWorkerId),type:NOTIFICATION_TYPES.SERVICE_IN_PROGRESS,title:"Service Approved",message:`Customer approved the estimate for ${id}. Service can now begin.`,bookingId:id,eventKey:`service-start-${id}-${phase9WorkerUserId(b.primaryWorkerId)}`});toast("Estimate accepted. Service can now begin.");}else{b.status=BOOKING_STATUSES.CANCELLED;b.cancellationReason="Estimate declined";state.assignments.filter(a=>a.bookingId===id&&a.status!==ASSIGNMENT_STATUSES.COMPLETED).forEach(a=>a.status=ASSIGNMENT_STATUSES.CANCELLED);phase9NotifyBookingEvent(state,b,BOOKING_STATUSES.CANCELLED);toast("Estimate declined. Booking cancelled.","info");}b.updatedAt=now;saveState(state);renderView("bookings");}

function payDemoPayment(id){if(role!=="customer")return;const state=getState(),b=state.bookings.find(x=>x.id===id),p=state.payments.find(x=>x.bookingId===id&&x.type==="service");if(!b||b.customerId!==currentCustomer()?.id||b.status!==BOOKING_STATUSES.COMPLETED)return toast("Demo payment is available only for your completed booking.","error");if(!p)return toast("No service payment is due for this booking.","info");if(p.status===PAYMENT_STATUSES.PAID)return toast("This demo payment is already marked as paid.","info");p.status=PAYMENT_STATUSES.PAID;p.paidAt=new Date().toISOString();b.paymentStatus=PAYMENT_STATUSES.PAID;b.payment="Paid · Demo";b.updatedAt=new Date().toISOString();saveState(state);createNotification({recipientId:phase9WorkerUserId(b.primaryWorkerId),type:NOTIFICATION_TYPES.SYSTEM,title:"Demo Payment Received",message:`Demo payment for ${id} has been marked as paid.`,bookingId:id,eventKey:`payment-${id}-${phase9WorkerUserId(b.primaryWorkerId)}`});toast("Demo payment completed.","success");renderView("payments");}
