renderView=function(view){if(view==="notifications"){$("#dashTitle").textContent=(localizedNavs()[role]||[]).find(x=>x[0]==="notifications")?.[1]||"Notifications";phase9NotificationView($("#dashContent"));phase9RefreshNotificationUI();return}_renderViewPhase9b(view);phase9RefreshNotificationUI();};
