  function workerMapStatus(w, bookings){
    const related=bookings.filter(b=>getBookingWorker(b)?.id===w.id).sort((a,b)=>String(b.updatedAt||b.date||'').localeCompare(String(a.updatedAt||a.date||'')));
    const latest=related[0];
    if(latest && latest.status===BOOKING_STATUSES.COMPLETED) return {key:'completed',label:'JOB COMPLETED',booking:latest};
    if(w.active===false || w.online===false) return {key:'offline',label:'OFFLINE',booking:latest&&isActive(latest)?latest:null};
    if(latest && latest.status===BOOKING_STATUSES.ON_THE_WAY) return {key:'onway',label:'ON THE WAY',booking:latest};
    if(latest && isActive(latest)) return {key:'busy',label:'BUSY / WORKING',booking:latest};
    return {key:'available',label:'AVAILABLE',booking:null};
  }
  function workerMapLocation(w, index){
    const base=areaCoordinates(w.area||w.serviceAreas?.[0]||'Pune')||areaCoordinates('Pune')||[18.5204,73.8567];
    const offsets=[[0,0],[0.006,-0.004],[-0.005,0.005],[0.004,0.006],[-0.006,-0.003],[0.008,0.002]];
    const o=offsets[index%offsets.length];
    return {lat:base[0]+o[0],lng:base[1]+o[1],label:w.area||w.serviceAreas?.[0]||'Pune'};
  }
  function workerMapJobLocation(b){
    if(!b)return null;
    const c=bookingCoordinates(b); return c?{lat:c.lat,lng:c.lng,label:b.location||'Pune'}:null;
  }
  function workerMapMarkerClass(key){return `worker-map-marker worker-map-${key}`;}
  function renderWorkerLocationMap(){
    const root=document.getElementById('workerLocationMapSection'); if(!root)return;
    const workers=federationWorkers(), bookings=federationBookings();
    root.innerHTML=`<div class="worker-location-card-head"><div><span class="eyebrow">WORKFORCE VISIBILITY</span><h3>Worker Locations</h3><p>See worker location, availability and assigned jobs. Locations shown below are demo/last-updated locations, not live GPS.</p></div><span class="status-pill blue">Demo Location</span></div><div class="worker-map-controls"><div class="worker-map-filters" role="group" aria-label="Worker status filter"><button type="button" class="worker-map-filter active" data-filter="all">All</button><button type="button" class="worker-map-filter" data-filter="available">Available</button><button type="button" class="worker-map-filter" data-filter="busy">Busy</button><button type="button" class="worker-map-filter" data-filter="onway">On the Way</button><button type="button" class="worker-map-filter" data-filter="offline">Offline</button></div><div class="worker-map-actions"><select id="workerMapSelect" aria-label="Locate worker"><option value="">Locate / select worker</option>${workers.map(w=>`<option value="${escHtml(w.id)}">${escHtml(w.name)} · ${escHtml(w.id)}</option>`).join('')}</select><button type="button" class="btn btn-outline" id="workerMapFit">Fit all workers</button></div></div><div id="workerLocationMap" class="worker-location-map" aria-label="Worker location and availability map"></div><div class="worker-map-legend"><span><i class="wm-dot available"></i> Available — Can accept job</span><span><i class="wm-dot busy"></i> Busy / Working — Currently working</span><span><i class="wm-dot onway"></i> On the Way — Travelling to job</span><span><i class="wm-dot completed"></i> Job Completed — Latest job completed</span><span><i class="wm-dot offline"></i> Offline — Not currently active</span></div><div class="worker-map-note">Demo / Last Updated Location · Real-time GPS can be connected when location services are available.</div>`;
    if(typeof L==='undefined')return;
    const map=L.map('workerLocationMap',{scrollWheelZoom:false}).setView([18.5204,73.8567],12);
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors'}).addTo(map);
    const records=workers.map((w,i)=>{const st=workerMapStatus(w,bookings),loc=workerMapLocation(w,i),job=workerMapJobLocation(st.booking);return {w,st,loc,job}});
    const layer=L.layerGroup().addTo(map), routes=L.layerGroup().addTo(map), markerById=new Map();
    function popup(r){
      const b=r.st.booking, jobName=b?(SERVICES.find(s=>s.id===b.service)?.name||b.service):'—';
      return `<div class="worker-map-popup"><b>Worker: ${escHtml(r.w.name)}</b><div>ID: ${escHtml(r.w.id)}</div><div>Skill / Service: ${escHtml(r.w.skill||r.w.service||'—')}</div><div>Status: <strong>${escHtml(r.st.label)}</strong></div><div>Current Assigned Job: ${escHtml(jobName)}</div><div>Worker Location: ${escHtml(r.loc.label)}</div><div>Job Location: ${escHtml(r.job?.label||'—')}</div><div>Last Location Update: ${escHtml(r.w.lastLocationUpdate||'5 min ago')} <small>(demo)</small></div></div>`;
    }
    function draw(filter='all'){
      layer.clearLayers(); routes.clearLayers(); markerById.clear();
      const visible=records.filter(r=>filter==='all'||r.st.key===filter);
      visible.forEach(r=>{const marker=L.marker([r.loc.lat,r.loc.lng],{icon:L.divIcon({className:'worker-map-icon-wrap',html:`<span class="${workerMapMarkerClass(r.st.key)}">${escHtml(String(r.w.name||'W').slice(0,1).toUpperCase())}</span>`,iconSize:[34,34],iconAnchor:[17,17]})}).addTo(layer).bindPopup(popup(r));markerById.set(r.w.id,marker);if(r.job&&(r.st.key==='busy'||r.st.key==='onway')){L.polyline([[r.loc.lat,r.loc.lng],[r.job.lat,r.job.lng]],{weight:3,dashArray:r.st.key==='onway'?'8 7':'3 5',opacity:.7}).addTo(routes);L.circleMarker([r.job.lat,r.job.lng],{radius:5,weight:2,fillOpacity:.85}).addTo(routes).bindTooltip(`Job: ${escHtml(r.job.label)}`);}});
      if(visible.length){const bounds=L.latLngBounds(visible.map(r=>[r.loc.lat,r.loc.lng]));map.fitBounds(bounds.pad(.2),{maxZoom:13});}else map.setView([18.5204,73.8567],12);
    }
    root.querySelectorAll('.worker-map-filter').forEach(btn=>btn.addEventListener('click',()=>{root.querySelectorAll('.worker-map-filter').forEach(b=>b.classList.remove('active'));btn.classList.add('active');draw(btn.dataset.filter);root.querySelector('#workerMapSelect').value='';}));
    root.querySelector('#workerMapFit').addEventListener('click',()=>{const active=root.querySelector('.worker-map-filter.active')?.dataset.filter||'all';draw(active);});
    root.querySelector('#workerMapSelect').addEventListener('change',ev=>{const id=ev.target.value;if(!id)return;const r=records.find(x=>x.w.id===id);if(!r)return;root.querySelectorAll('.worker-map-filter').forEach(b=>b.classList.remove('active'));root.querySelector('.worker-map-filter[data-filter="all"]').classList.add('active');draw('all');map.setView([r.loc.lat,r.loc.lng],15);markerById.get(id)?.openPopup();});
    draw('all'); setTimeout(()=>map.invalidateSize(),120);
  }

